app.get('/api/tmdb/search', async (req, res) => {
    try {
        const query = req.query.q;
        if (!query) return res.status(400).json({ error: 'Missing search query' });
        const tmdbKey = TMDB_API_KEY;
        // Multi-search endpoint returns both movies and TV
        const url = `${TMDB_BASE_URL}/search/multi?api_key=${tmdbKey}&query=${encodeURIComponent(query)}`;
        const tmdbRes = await axios.get(url);
        // Filter to only movies and TV (ignore people, etc)
        const results = (tmdbRes.data.results || []).filter(item => item.media_type === 'movie' || item.media_type === 'tv');
        // Normalize results for frontend
        const normalized = results.map(item => ({
            id: item.id,
            title: item.title || item.name,
            poster: item.poster_path ? `${TMDB_IMAGE_BASE}${item.poster_path}` : '',
            year: (item.release_date || item.first_air_date || '').slice(0, 4),
            type: item.media_type,
            overview: item.overview || ''
        }));
        res.json(normalized);
    } catch (err) {
        console.error('[TMDB Multi-Search] Error:', err.message);
        res.status(500).json({ error: 'Failed to fetch from TMDB' });
    }
});

// A few hours, not days - "currently airing" genuinely shifts as the day goes on (a show
// crossing into/out of the vote_count floor, a new episode nudging popularity), unlike the
// curated homepage rows (ANIME_ROW_CACHE_TTL, 48h) which are fine sitting stale far longer.
// Still turns "two live TMDB discover calls on literally every homepage visit" into "one live
// call every few hours, everyone else served from SQLite."
const TMDB_DISCOVER_CACHE_TTL = 3 * 60 * 60 * 1000; // 3 hours

function tmdbDiscoverCacheGet(cacheKey) {
    return new Promise((resolve) => {
        animeCacheDb.get(
            `SELECT json, cached_at FROM tmdb_discover_cache WHERE cache_key = ?`,
            [cacheKey],
            (err, row) => {
                if (err || !row) return resolve(null);
                if (Date.now() - row.cached_at > TMDB_DISCOVER_CACHE_TTL) return resolve(null);
                try {
                    resolve(JSON.parse(row.json));
                } catch {
                    resolve(null);
                }
            }
        );
    });
}

function tmdbDiscoverCacheSet(cacheKey, data) {
    animeCacheDb.run(
        `INSERT INTO tmdb_discover_cache (cache_key, json, cached_at) VALUES (?, ?, ?)
         ON CONFLICT(cache_key) DO UPDATE SET json = excluded.json, cached_at = excluded.cached_at`,
        [cacheKey, JSON.stringify(data), Date.now()],
        (err) => { if (err) console.warn('[TMDB Discover Cache] write failed:', err.message); }
    );
}

// Detail data (title, overview, poster, genres...) for a given show/movie is effectively
// immutable on the timescale this app cares about - a few hours of staleness is invisible to
// users but turns "every hero candidate + every episode badge hits TMDB live" into "one live
// call per show every few hours, everyone else served from SQLite."
const TMDB_DETAIL_CACHE_TTL = 6 * 60 * 60 * 1000; // 6 hours

function tmdbDetailCacheGet(cacheKey) {
    return new Promise((resolve) => {
        animeCacheDb.get(
            `SELECT json, cached_at FROM tmdb_detail_cache WHERE cache_key = ?`,
            [cacheKey],
            (err, row) => {
                if (err || !row) return resolve(null);
                if (Date.now() - row.cached_at > TMDB_DETAIL_CACHE_TTL) return resolve(null);
                try {
                    resolve(JSON.parse(row.json));
                } catch {
                    resolve(null);
                }
            }
        );
    });
}

function tmdbDetailCacheSet(cacheKey, data) {
    animeCacheDb.run(
        `INSERT INTO tmdb_detail_cache (cache_key, json, cached_at) VALUES (?, ?, ?)
         ON CONFLICT(cache_key) DO UPDATE SET json = excluded.json, cached_at = excluded.cached_at`,
        [cacheKey, JSON.stringify(data), Date.now()],
        (err) => { if (err) console.warn('[TMDB Detail Cache] write failed:', err.message); }
    );
}

// A person's own TV filmography barely ever changes - a new show credit appearing is a rare,
// slow event compared to how often movieInfo.html's Director/Actor rows re-request it (every
// single page load, no caching at all before this - confirmed live loading movieInfo.html for
// Attack on Titan: /person/{id}/tv_credits hit TMDB live every time). 180 days, same long tier
// this session's other "barely ever changes" caches (finished anime season structure, etc) use.
const TMDB_PERSON_CREDITS_CACHE_TTL = 180 * 24 * 60 * 60 * 1000;

function tmdbPersonCreditsCacheGet(cacheKey) {
    return new Promise((resolve) => {
        animeCacheDb.get(
            `SELECT json, cached_at FROM tmdb_person_credits_cache WHERE cache_key = ?`,
            [cacheKey],
            (err, row) => {
                if (err || !row) return resolve(null);
                if (Date.now() - row.cached_at > TMDB_PERSON_CREDITS_CACHE_TTL) return resolve(null);
                try {
                    resolve(JSON.parse(row.json));
                } catch {
                    resolve(null);
                }
            }
        );
    });
}

function tmdbPersonCreditsCacheSet(cacheKey, data) {
    animeCacheDb.run(
        `INSERT INTO tmdb_person_credits_cache (cache_key, json, cached_at) VALUES (?, ?, ?)
         ON CONFLICT(cache_key) DO UPDATE SET json = excluded.json, cached_at = excluded.cached_at`,
        [cacheKey, JSON.stringify(data), Date.now()],
        (err) => { if (err) console.warn('[TMDB Person Credits Cache] write failed:', err.message); }
    );
}

// --- TMDB Proxy (keeps the API key out of the browser) ---
// Frontend calls /api/tmdb-proxy/tv/123?language=en-US
// → this route adds the key and forwards to https://api.themoviedb.org/3/tv/123
app.use('/api/tmdb-proxy', async (req, res) => {
    try {
        const tmdbPath = req.path;
        const query    = { ...req.query, api_key: TMDB_API_KEY };

        // Discover queries (currently only hit by the homepage's "Currently Airing" row) used
        // to go straight to TMDB live on every single request - see tmdbDiscoverCacheGet's
        // comment above the TTL constant.
        if (tmdbPath === '/discover/tv' || tmdbPath === '/discover/movie') {
            const cacheKey = `${tmdbPath}?${new URLSearchParams(req.query).toString()}`;
            const cached = await tmdbDiscoverCacheGet(cacheKey);
            if (cached) return res.json(cached);

            const tmdbRes = await axios.get(`${TMDB_BASE_URL}${tmdbPath}`, {
                params: query,
                headers: { Accept: 'application/json' },
            });
            tmdbDiscoverCacheSet(cacheKey, tmdbRes.data);
            return res.json(tmdbRes.data);
        }

        // /person/{id}/tv_credits - powers movieInfo.html's Director/Cast rows. A person's own
        // filmography barely ever changes, hence the long 180-day TTL (see
        // TMDB_PERSON_CREDITS_CACHE_TTL) rather than the few-hours tiers above.
        const personCreditsMatch = tmdbPath.match(/^\/person\/(\d+)\/tv_credits$/);
        if (personCreditsMatch) {
            const cacheKey = `${tmdbPath}?${new URLSearchParams(req.query).toString()}`;
            const cached = await tmdbPersonCreditsCacheGet(cacheKey);
            if (cached) return res.json(cached);

            const tmdbRes = await axios.get(`${TMDB_BASE_URL}${tmdbPath}`, {
                params: query,
                headers: { Accept: 'application/json' },
            });
            tmdbPersonCreditsCacheSet(cacheKey, tmdbRes.data);
            return res.json(tmdbRes.data);
        }

        // Plain detail lookup: /tv/{id} or /movie/{id}, no further path segments. Keyed by the
        // full query string (not just tmdbId) so an `append_to_response=...` variant (used by
        // movieInfo's full detail fetch) never collides with the bare lookup hero/badges use.
        const detailMatch = tmdbPath.match(/^\/(tv|movie)\/(\d+)$/);
        if (detailMatch) {
            const cacheKey = `${tmdbPath}?${new URLSearchParams(req.query).toString()}`;
            const cached = await tmdbDetailCacheGet(cacheKey);
            if (cached) return res.json(cached);

            const tmdbRes = await axios.get(`${TMDB_BASE_URL}${tmdbPath}`, {
                params: query,
                headers: { Accept: 'application/json' },
            });
            tmdbDetailCacheSet(cacheKey, tmdbRes.data);
            return res.json(tmdbRes.data);
        }

        // Check if this is a season request: /tv/{id}/season/{num}
        const seasonMatch = tmdbPath.match(/^\/tv\/(\d+)\/season\/(\d+)$/);
        if (seasonMatch) {
            const tmdbId = Number(seasonMatch[1]);
            const seasonNum = Number(seasonMatch[2]);

            const cached = await new Promise((resolve) => {
                animeCacheDb.all(`
                    SELECT episode_number, title, air_date, overview, still_path, runtime
                    FROM episode_cache
                    WHERE tmdb_id = ? AND season_number = ?
                    ORDER BY episode_number ASC
                `, [tmdbId, seasonNum], (err, rows) => {
                    if (err) {
                        console.warn('[TMDB Cache] read failed:', err.message);
                        resolve(null);
                    } else {
                        resolve(rows);
                    }
                });
            });

            logEpisodeCache(`Cache CHECK ${tmdbId} S${seasonNum}: ${cached ? cached.length : 0} rows found`);

            // "Settled" = every cached episode has actually aired (a real, non-future
            // air_date) - once true, nothing about that season changes again (titles,
            // stills, dates are all final), so it's safe to serve indefinitely. This
            // replaces the old all-fields-non-null check, which meant a single episode
            // missing just a thumbnail (extremely common for anything not yet aired)
            // discarded caching for the ENTIRE season, every time -- in practice the
            // cache almost never got used at all. Missing fields are fine now; only
            // "hasn't aired yet" blocks serving from cache.
            const today = new Date().toISOString().slice(0, 10);
            const isSettled = !!cached && cached.length > 0 && cached.every(ep => ep.air_date && ep.air_date <= today);

            if (isSettled) {
                logEpisodeCache(`✓ Cache HIT ${tmdbId} S${seasonNum}: serving ${cached.length} settled episodes`);
                // Transform cached episodes: rename 'title' to 'name' to match TMDB API response format
                const normalizedEpisodes = cached.map(ep => ({
                    episode_number: ep.episode_number,
                    name: ep.title,  // Database stores as 'title', but TMDB API uses 'name'
                    air_date: ep.air_date,
                    overview: ep.overview,
                    still_path: ep.still_path,
                    runtime: ep.runtime
                }));
                return res.json({
                    episodes: normalizedEpisodes,
                    _cached: true
                });
            }
            logEpisodeCache(cached && cached.length > 0
                ? `Cache STALE ${tmdbId} S${seasonNum}: season still resolving (unaired/missing air_date episode present), refetching`
                : `Cache MISS ${tmdbId} S${seasonNum} (0 rows)`);
        }

        // Not cached (or not settled yet), fetch from TMDB
        const tmdbRes  = await axios.get(`${TMDB_BASE_URL}${tmdbPath}`, {
            params:  query,
            headers: { Accept: 'application/json' },
        });

        // Cache season episodes if applicable
        if (seasonMatch && tmdbRes.data?.episodes) {
            const tmdbId = Number(seasonMatch[1]);
            const seasonNum = Number(seasonMatch[2]);
            const episodes = tmdbRes.data.episodes;

            logEpisodeCache(`TMDB response ${tmdbId} S${seasonNum}: ${episodes.length} episodes (ep1="${episodes[0]?.name || 'N/A'}", air_date="${episodes[0]?.air_date || 'N/A'}")`);
            logEpisodeCache(`Cache WRITE START ${tmdbId} S${seasonNum}: deleting old data...`);

            // Cache whatever TMDB actually returned, missing fields and all -- an
            // episode without a still_path/air_date yet still gets cached, it just
            // won't count as "settled" above, so it'll be refetched again next time
            // instead of silently blocking the whole season from ever caching.
            animeCacheDb.run(`
                DELETE FROM episode_cache
                WHERE tmdb_id = ? AND season_number = ?
            `, [tmdbId, seasonNum], (deleteErr) => {
                if (deleteErr) {
                    logEpisodeCache(`Cache DELETE error: ${deleteErr.message}`);
                    return;
                }

                logEpisodeCache(`Cache DELETE done for ${tmdbId} S${seasonNum}, inserting ${episodes.length} episodes...`);

                let inserted = 0;
                const insertNext = () => {
                    if (inserted >= episodes.length) {
                        logEpisodeCache(`Cache WRITE DONE ${tmdbId} S${seasonNum}: all ${episodes.length} episodes inserted ✓`);
                        return;
                    }

                    const ep = episodes[inserted];
                    animeCacheDb.run(`
                        INSERT INTO episode_cache
                        (tmdb_id, season_number, episode_number, title, air_date, still_path, runtime, overview, cached_at)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                    `, [
                        tmdbId,
                        seasonNum,
                        ep.episode_number,
                        ep.name || null,
                        ep.air_date || null,
                        ep.still_path || null,
                        ep.runtime || 0,
                        ep.overview || '',
                        Date.now()
                    ], (insertErr) => {
                        if (insertErr) {
                            logEpisodeCache(`Cache INSERT error ep${ep.episode_number}: ${insertErr.message}`);
                        }
                        inserted++;
                        insertNext();
                    });
                };

                insertNext();
            });
        }

        res.json(tmdbRes.data);
    } catch (err) {
        const status = err.response?.status || 500;
        res.status(status).json({ error: 'TMDB proxy error', detail: err.message });
    }
});

// ── Cached TMDB recommendations/similar ────────────────────────────────────────
// Cache-first: serve from movieCache.db when fresh, otherwise fetch live (trying
// /recommendations first, falling back to /similar if empty) and store whichever
// succeeded. Used for both regular movie/TV recommendations AND as the fallback
// target when anime mode's AniList-based recommendations come back empty/down --
// one cache serves both paths since they render into the same "Recommended" row.
const MOVIE_REC_REFRESH_MS = 3 * 24 * 60 * 60 * 1000;

function movieRecGet(tmdbId, mediaType) {
    return new Promise((resolve, reject) => {
        movieCacheDb.get(
            `SELECT json, source, cached_at FROM tmdb_recommendations WHERE tmdb_id = ? AND media_type = ?`,
            [tmdbId, mediaType],
            (err, row) => {
                if (err) return reject(err);
                if (!row) return resolve(null);
                const now = Date.now();
                movieCacheDb.run(
                    `UPDATE tmdb_recommendations SET last_accessed = ? WHERE tmdb_id = ? AND media_type = ?`,
                    [now, tmdbId, mediaType]
                );
                resolve(row);
            }
        );
    });
}

function movieRecUpsert(tmdbId, mediaType, source, resultsJson) {
    return new Promise((resolve, reject) => {
        const now = Date.now();
        movieCacheDb.run(
            `INSERT INTO tmdb_recommendations (tmdb_id, media_type, source, json, cached_at, last_accessed)
             VALUES (?, ?, ?, ?, ?, ?)
             ON CONFLICT(tmdb_id, media_type) DO UPDATE SET
                 source = excluded.source,
                 json = excluded.json,
                 cached_at = excluded.cached_at,
                 last_accessed = excluded.last_accessed`,
            [tmdbId, mediaType, source, resultsJson, now, now],
            (err) => err ? reject(err) : resolve()
        );
    });
}

app.get('/api/movie-recommendations', async (req, res) => {
    const tmdbId = parseInt(req.query.tmdbId, 10);
    const mediaType = req.query.type === 'tv' ? 'tv' : 'movie';
    if (!tmdbId) return res.status(400).json({ error: 'Missing tmdbId' });

    let cached = null;
    try {
        cached = await movieRecGet(tmdbId, mediaType);
    } catch (err) {
        console.warn('[Movie Recommendations] cache read failed', err.message);
    }

    if (cached && (Date.now() - cached.cached_at) < MOVIE_REC_REFRESH_MS) {
        return res.json({ results: JSON.parse(cached.json), source: cached.source, cached: true });
    }

    try {
        let source = 'recommendations';
        let response = await axios.get(
            `${TMDB_BASE_URL}/${mediaType}/${tmdbId}/recommendations`,
            { params: { api_key: TMDB_API_KEY, language: 'en-US', page: 1 } }
        ).catch(() => null);
        let results = response?.data?.results || [];

        if (!results.length) {
            source = 'similar';
            response = await axios.get(
                `${TMDB_BASE_URL}/${mediaType}/${tmdbId}/similar`,
                { params: { api_key: TMDB_API_KEY, language: 'en-US', page: 1 } }
            ).catch(() => null);
            results = response?.data?.results || [];
        }

        if (results.length) {
            await movieRecUpsert(tmdbId, mediaType, source, JSON.stringify(results));
            return res.json({ results, source, cached: false });
        }

        if (cached) {
            return res.json({ results: JSON.parse(cached.json), source: cached.source, cached: true, stale: true });
        }
        return res.json({ results: [], source, cached: false });
    } catch (err) {
        console.error('[Movie Recommendations] live fetch failed', err.message);
        if (cached) {
            return res.json({ results: JSON.parse(cached.json), source: cached.source, cached: true, stale: true });
        }
        return res.status(502).json({ error: 'Failed to fetch recommendations' });
    }
});

