// Minimal AniList Media lookup by either its own id or its MAL id -- just enough
// (title variants + cover) to search TMDB with when neither Fribb's list nor the
// anime_tmdb_mapping cache already has a tmdb_id for that id.
async function aniListGetMediaBasic({ anilistId, malId }) {
    const query = `
        query ($id: Int, $idMal: Int) {
            Media(id: $id, idMal: $idMal, type: ANIME) {
                id
                idMal
                title { romaji english native }
                coverImage { extraLarge large }
                episodes
                format
            }
        }
    `;
    const variables = {};
    if (anilistId) variables.id = anilistId;
    if (malId) variables.idMal = malId;

    const response = await axios.post(
        'https://graphql.anilist.co',
        { query, variables },
        { headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' }, timeout: 15000 }
    );
    return response.data?.data?.Media || null;
}

function animeTmdbMappingUpsert({ tmdbId, malId = null, anilistId = null, title = null }) {
    return new Promise((resolve, reject) => {
        const now = Date.now();
        const values = [tmdbId, malId, anilistId, title, now];
        animeCacheDb.run(
            `INSERT INTO anime_tmdb_mapping (tmdb_id, mal_id, anilist_id, title, cached_at)
             VALUES (?, ?, ?, ?, ?)
             ON CONFLICT(tmdb_id) DO UPDATE SET
                 mal_id = COALESCE(excluded.mal_id, anime_tmdb_mapping.mal_id),
                 anilist_id = COALESCE(excluded.anilist_id, anime_tmdb_mapping.anilist_id),
                 title = COALESCE(excluded.title, anime_tmdb_mapping.title),
                 cached_at = excluded.cached_at`,
            values,
            function (err) {
                if (err) return reject(err);
                resolve(this.changes || 0);
            }
        );
        console.log('[Mapping Upsert]');
        console.log({
            tmdbId,
            malId,
            anilistId,
            title
        });
    });
}

// Confirms a cached tmdb_id is still Japanese-origin content in EITHER the tv or movie
// namespace - the same check the badge pipeline's genre/origin gate already uses (see
// getTmdbAnimeTitle's comment), reused here for the same reason: a wrong mapping (an
// AniList anime id pointed at an unrelated Western show/movie, or an id that's since 404ing)
// is virtually always non-Japanese or nonexistent, so this catches it without needing to know
// what the ORIGINAL AniList entry's format/title even were.
async function isTmdbIdStillJapaneseAnime(tmdbId) {
    for (const mediaType of ['tv', 'movie']) {
        try {
            const data = await tmdbGet(`/${mediaType}/${tmdbId}`, { language: 'en-US' });
            const isJapanese = data?.original_language === 'ja' ||
                (Array.isArray(data?.origin_country) && data.origin_country.includes('JP'));
            if (isJapanese) return true;
        } catch (err) { /* 404 or other failure - try the other media type / fall through */ }
    }
    return false;
}

// Throttled background cleanup for anime_tmdb_mapping - see validated_at's migration comment
// for why this exists at all. Small batch per run (never a burst that could trip TMDB's own
// rate limiting, the same mistake the old unbounded MegaPlay/TMDB-search cascades made earlier
// this session) - a full first pass over an existing ~1700-row table spreads out over hours
// rather than happening all at once, which is fine since this is pure cleanup, nothing user-
// facing is waiting on it.
const ANIME_TMDB_MAPPING_AUDIT_BATCH_SIZE = 25;
const ANIME_TMDB_MAPPING_AUDIT_REQUEST_SPACING_MS = 300;

async function runAnimeTmdbMappingAudit() {
    const rows = await new Promise((resolve, reject) => {
        animeCacheDb.all(
            `SELECT tmdb_id FROM anime_tmdb_mapping ORDER BY validated_at IS NOT NULL, validated_at ASC LIMIT ?`,
            [ANIME_TMDB_MAPPING_AUDIT_BATCH_SIZE],
            (err, r) => err ? reject(err) : resolve(r || [])
        );
    });
    if (!rows.length) return;

    let deleted = 0;
    for (const row of rows) {
        try {
            const stillValid = await isTmdbIdStillJapaneseAnime(row.tmdb_id);
            if (stillValid) {
                await new Promise((resolve, reject) => {
                    animeCacheDb.run(`UPDATE anime_tmdb_mapping SET validated_at = ? WHERE tmdb_id = ?`, [Date.now(), row.tmdb_id],
                        (err) => err ? reject(err) : resolve());
                });
            } else {
                await new Promise((resolve, reject) => {
                    animeCacheDb.run(`DELETE FROM anime_tmdb_mapping WHERE tmdb_id = ?`, [row.tmdb_id],
                        (err) => err ? reject(err) : resolve());
                });
                deleted++;
                logAnikotoDebug(`[TmdbMappingAudit] Deleted bad mapping for tmdb_id ${row.tmdb_id} - no longer resolves to Japanese-origin content in either namespace`);
            }
        } catch (err) {
            logAnikotoDebug(`[TmdbMappingAudit] Check failed for tmdb_id ${row.tmdb_id}`, { error: err.message || String(err) });
        }
        await sleep(ANIME_TMDB_MAPPING_AUDIT_REQUEST_SPACING_MS);
    }
    logHealthStatus(`[TmdbMappingAudit] Checked ${rows.length} mapping(s), deleted ${deleted} bad one(s)`);
}

async function searchTmdbAnimeIdByTitle(title, options = {}) {
    if (!title) return null;
    const query = String(title || '').trim();
    if (!query) return null;

    const mediaType = options.mediaType === 'movie' ? 'movie' : 'tv';
    console.log(` SEARCHING TMDB FOR TITLE: [${query}] type=${mediaType}`);
    appendTmdbLogLine(`[TMDB SEARCH] type=${mediaType} query="${query}"`);

    try {
        const response = await tmdbGet(`/search/${mediaType}`, {
            query,
            language: 'en-US',
            page: 1
        });
        const results = Array.isArray(response.results) ? response.results : [];
        const normalize = (value) => String(value || '').trim().toLowerCase();
        const searchText = normalize(query);

        const fieldName = mediaType === 'movie' ? 'title' : 'name';
        const fieldOriginal = mediaType === 'movie' ? 'original_title' : 'original_name';
        const isJapaneseOrigin = item => item?.original_language === 'ja' ||
            (Array.isArray(item?.origin_country) && item.origin_country.includes('JP'));
        // TMDB sorts by popularity, and a real anime frequently shares its exact title with an
        // unrelated non-Japanese show (confirmed live: "One Piece" the anime, tmdb 37854/ja/JP,
        // lost to "ONE PIECE" the 2023 Netflix live-action, tmdb 111110/en/US, because the live-
        // action's higher popularity put it first in results and .find() just took the first
        // exact match). Among several equally-exact (or equally-partial) matches, prefer whichever
        // one is actually Japanese-origin instead of trusting API result order.
        const pickBestMatch = predicate => {
            const matches = results.filter(item => predicate(normalize(item[fieldName] || item[fieldOriginal])));
            if (!matches.length) return undefined;
            return matches.find(isJapaneseOrigin) || matches[0];
        };

        const exactMatch = pickBestMatch(name => name === searchText);
        const partialMatch = pickBestMatch(name => name.includes(searchText) || searchText.includes(name));
        const chosenId = exactMatch?.id || partialMatch?.id || results[0]?.id || null;
        appendTmdbLogLine(`[TMDB SEARCH RESULT] type=${mediaType} query="${query}" count=${results.length} exact=${exactMatch?.id || 'none'} partial=${partialMatch?.id || 'none'} chosen=${chosenId || 'none'}`);

        if (typeof options.onResponse === 'function') {
            try {
                options.onResponse({ query, mediaType, results, exactMatchId: exactMatch?.id || null, partialMatchId: partialMatch?.id || null, chosenId });
            } catch (logErr) {
                console.error('[TMDB LOG CALLBACK] failed:', logErr.message || logErr);
            }
        }

        if (exactMatch) return exactMatch.id;
        if (partialMatch) return partialMatch.id;

        // No confident TV match - before blindly trusting whatever TMDB's tv search happened to
        // rank #1 (confirmed live: "Kimi no Na wa." - actually a MOVIE, "Your Name." - got mapped
        // to a totally unrelated TV show, "Name Your Adventure", purely because the primary
        // resolution loop only ever searches /search/tv, never /search/movie, for the primary
        // title; movie search only kicked in later, for a SHORTENED fallback title, by which
        // point the wrong tv id had already been cached and returned). An exact/partial MOVIE
        // match on the SAME query is real evidence a tv position-0 guess never was.
        if (mediaType === 'tv' && !options._movieRetried) {
            const movieId = await searchTmdbAnimeIdByTitle(title, { ...options, mediaType: 'movie', _movieRetried: true });
            if (movieId) return movieId;
        }

        // requireConfidence: never fall back to a bare position-0 guess - only for callers whose
        // query already had something stripped off it (see getTmdbIdForAniList's fallback tier).
        // Confirmed live this is exactly how "Youjo Senki II" (Season 2) got mapped to a wrong
        // tmdb_id: the fallback tier strips "II" - the ONE word distinguishing this season from
        // the rest of the franchise - searches the now-ambiguous bare "Youjo Senki", gets a single
        // unrelated result, and (before this flag existed) trusted it outright with zero
        // corroboration. A query that's already had its season/qualifier text stripped is a much
        // weaker signal than a caller's original, full title - not safe to guess from at all.
        if (options.requireConfidence) return null;

        if (!results.length) return null;
        return results[0]?.id || null;
    } catch (err) {
        console.warn('[Anime TMDB Lookup] failed for title:', title, err.message || err);
        appendTmdbLogLine(`[TMDB SEARCH ERROR] type=${mediaType} query="${query}" error="${err.message || err}"`);
        if (typeof options.onResponse === 'function') {
            try {
                options.onResponse({ query, mediaType, results: [], exactMatchId: null, partialMatchId: null, chosenId: null, error: err.message || String(err) });
            } catch (logErr) {
                console.error('[TMDB LOG CALLBACK] failed:', logErr.message || logErr);
            }
        }
        return null;
    }
}

function cleanAnimeSearchTitle(title) {
    if (!title) return null;
    let cleaned = String(title).trim();
    if (!cleaned) return null;

    const suffixPatterns = [
        /\bSeason\s*\d+\b$/i,
        /\b\d+(?:st|nd|rd|th)\s*[Ss]eason\b$/i,
        /\bSeason\s*(?:I|II|III|IV|V|VI|VII|VIII|IX|X)\b$/i,
        /\bPart\s*\d+\b$/i,
        /\bCour\s*\d+\b$/i,
        /\b(?:I|II|III|IV|V|VI|VII|VIII|IX|X)\b$/i,
        /\b\d+\b$/
    ];

    let previous;
    do {
        previous = cleaned;
        cleaned = cleaned.replace(/[\s:–—-]+$/, '').trim();
        suffixPatterns.forEach(pattern => {
            cleaned = cleaned.replace(pattern, '').trim();
        });
    } while (cleaned !== previous);

    return cleaned || null;
}

// Returns { full, stripped } instead of one flat list - cleanAnimeSearchTitle strips season/
// qualifier suffixes ("Season N", roman numerals, trailing digits), and confirmed live that's
// exactly what turned "Youjo Senki II" into the genuinely ambiguous "Youjo Senki" (matches
// Season 1, Season 2, OVAs, and the movie all at once). A stripped variant is a strictly weaker
// signal than the caller's own full title and needs to be searched with requireConfidence - see
// searchTmdbAnimeIdByTitle's comment for the wrong-tmdb_id case this caused.
function buildAniListSearchTitles({ title, englishTitle, romajiTitle, nativeTitle }) {
    const full = [];
    const stripped = [];
    const addTo = (list, value) => {
        const normalized = String(value || '').trim();
        if (!normalized) return;
        if (!full.includes(normalized) && !stripped.includes(normalized)) list.push(normalized);
    };

    addTo(full, romajiTitle);
    addTo(stripped, cleanAnimeSearchTitle(romajiTitle));
    addTo(full, englishTitle || title);
    addTo(stripped, cleanAnimeSearchTitle(englishTitle || title));
    addTo(full, nativeTitle);

    return { full, stripped };
}

function normalizeTmdbFallbackTitle(title) {
    if (!title) return null;
    let cleaned = String(title || '').trim().toLowerCase();
    cleaned = cleaned.replace(/\b(animation|anime)\b/g, '');
    cleaned = cleaned.replace(/[^a-z0-9\s]+/gi, ' ');
    cleaned = cleaned.replace(/\s+/g, ' ').trim();
    return cleaned || null;
}

function buildTmdbFallbackTitles(title) {
    const variants = [];
    const cleaned = normalizeTmdbFallbackTitle(title);
    if (!cleaned) return variants;

    if (cleaned !== String(title || '').trim().toLowerCase()) {
        variants.push(cleaned);
    }

    const words = cleaned.split(' ').filter(Boolean);
    for (let i = words.length - 1; i >= 1; i--) {
        const shorter = words.slice(0, i).join(' ');
        if (shorter && !variants.includes(shorter)) {
            variants.push(shorter);
        }
    }

    return variants;
}

async function getTmdbIdForAniList(anilistId, title, malId = null, titleEnglish = null, titleRomaji = null, titleNative = null) {
    const cached = await animeTmdbMappingGetByAniListId(anilistId);
    if (cached?.tmdb_id) {
        if (!cached.mal_id && malId) {
            await animeTmdbMappingUpsert({
                tmdbId: cached.tmdb_id,
                malId,
                anilistId,
                title: title || null
            });
        }
        return cached.tmdb_id;
    }

    const { full: fullTitles, stripped: strippedTitles } = buildAniListSearchTitles({
        title,
        englishTitle: titleEnglish,
        romajiTitle: titleRomaji,
        nativeTitle: titleNative
    });

    appendTmdbLogLine(`[AniList ${anilistId}] initial title variants full=${JSON.stringify(fullTitles)} stripped=${JSON.stringify(strippedTitles)}`);

    const triedTitles = new Set();
    // Each entry pairs a title with whether it's a season/qualifier-STRIPPED variant - a
    // position-0 guess is only safe to trust for the caller's own full, unaltered title.
    const searchTitles = [];
    for (const rawTitle of fullTitles) {
        const normalized = String(rawTitle || '').trim();
        if (!normalized || triedTitles.has(normalized)) continue;
        triedTitles.add(normalized);
        searchTitles.push({ title: normalized, stripped: false });
    }
    for (const rawTitle of strippedTitles) {
        const normalized = String(rawTitle || '').trim();
        if (!normalized || triedTitles.has(normalized)) continue;
        triedTitles.add(normalized);
        searchTitles.push({ title: normalized, stripped: true });
    }

    for (const { title: searchTitle, stripped } of searchTitles) {
        appendTmdbLogLine(`[AniList ${anilistId}] searching primary title="${searchTitle}"${stripped ? ' (stripped)' : ''}`);
        const tmdbId = await searchTmdbAnimeIdByTitle(searchTitle, { requireConfidence: stripped });
        if (tmdbId) {
            appendTmdbLogLine(`[AniList ${anilistId}] resolved tmdb_id=${tmdbId} from title="${searchTitle}"`);
            await animeTmdbMappingUpsert({
                tmdbId,
                malId,
                anilistId,
                title: title || null
            });
            return tmdbId;
        }
    }

    for (const { title: searchTitle } of searchTitles) {
        const fallbackTitles = buildTmdbFallbackTitles(searchTitle);
        if (!fallbackTitles.length) continue;

        appendTmdbLogLine(`[AniList ${anilistId}] fallback titles for "${searchTitle}" => ${JSON.stringify(fallbackTitles)}`);

        const fallbackAttempts = [];
        for (const fallbackTitle of fallbackTitles) {
            if (triedTitles.has(fallbackTitle)) continue;
            triedTitles.add(fallbackTitle);
            appendTmdbLogLine(`[AniList ${anilistId}] searching fallback title="${fallbackTitle}"`);

            const attemptData = {};
            // requireConfidence: this query has already had a trailing word stripped off (see
            // buildTmdbFallbackTitles) - confirmed live that word can be exactly the season
            // qualifier ("Youjo Senki II" -> "Youjo Senki"), making the stripped query genuinely
            // ambiguous between seasons/movies/OVAs of the same franchise. A confident exact/
            // partial match is still fine to trust; a bare "whatever TMDB ranked first" guess on
            // an already-weakened query is not.
            let tmdbId = await searchTmdbAnimeIdByTitle(fallbackTitle, {
                onResponse: info => Object.assign(attemptData, info),
                mediaType: 'tv',
                requireConfidence: true
            });

            fallbackAttempts.push({
                query: fallbackTitle,
                results: attemptData.results || [],
                chosenId: attemptData.chosenId || null,
                mediaType: 'tv'
            });

            if (!tmdbId) {
                appendTmdbLogLine(`[AniList ${anilistId}] tv fallback failed for "${fallbackTitle}", trying movie search`);
                const movieAttemptData = {};
                tmdbId = await searchTmdbAnimeIdByTitle(fallbackTitle, {
                    onResponse: info => Object.assign(movieAttemptData, info),
                    mediaType: 'movie',
                    requireConfidence: true
                });
                fallbackAttempts.push({
                    query: fallbackTitle,
                    results: movieAttemptData.results || [],
                    chosenId: movieAttemptData.chosenId || null,
                    mediaType: 'movie'
                });
            }

            if (tmdbId) {
                appendTmdbLogLine(`[AniList ${anilistId}] resolved tmdb_id=${tmdbId} from fallback title="${fallbackTitle}"`);
                appendTmdbFallbackBlock({
                    anilistId,
                    originalTitle: title || searchTitle,
                    searchTitle,
                    attempts: fallbackAttempts,
                    succeeded: true
                });
                await animeTmdbMappingUpsert({
                    tmdbId,
                    malId,
                    anilistId,
                    title: title || null
                });
                return tmdbId;
            }
        }

        if (fallbackAttempts.length) {
            appendTmdbFallbackBlock({
                anilistId,
                originalTitle: title || searchTitle,
                searchTitle,
                attempts: fallbackAttempts
            });
        }
    }

    appendTmdbLogLine(`[AniList ${anilistId}] no TMDB match found for any title variant`);
    return null;
}

app.get('/api/anime-tmdb-id', async (req, res) => {
    const anilistId = parseInt(req.query.anilistId, 10);
    const title = req.query.title ? String(req.query.title) : null;
    const titleEnglish = req.query.titleEnglish ? String(req.query.titleEnglish) : null;
    const titleRomaji = req.query.titleRomaji ? String(req.query.titleRomaji) : null;
    const titleNative = req.query.titleNative ? String(req.query.titleNative) : null;
    const malId = req.query.malId ? String(req.query.malId) : null;

    if (!anilistId) {
        return res.status(400).json({ error: 'Missing anilistId' });
    }

    try {
        const tmdbId = await getTmdbIdForAniList(anilistId, title, malId, titleEnglish, titleRomaji, titleNative);
        if (!tmdbId) {
            return res.status(404).json({ error: 'TMDB id not found for aniListId' });
        }
        res.json({ tmdb_id: tmdbId });
    } catch (err) {
        console.error('[Anime TMDB ID]', err.message || err);
        res.status(500).json({ error: 'Failed to resolve TMDB id' });
    }
});

function animeRecommendationsRowByTmdbId(tmdbId) {
    return new Promise((resolve, reject) => {
        animeCacheDb.get(
            `SELECT json FROM anime_recommendations WHERE tmdb_id = ?`,
            [tmdbId],
            (err, row) => {
                if (err) return reject(err);
                resolve(row || null);
            }
        );
    });
}

async function getTmdbAnimeTitle(tmdbId) {
    const anime = await tmdbGet(
        `/tv/${tmdbId}`,
        { language: 'en-US' }
    );

    // TMDB movie ids and TV ids are separate numbering spaces that overlap numerically - an
    // anime MOVIE routed through this (anime-badge) pipeline with its own movie-namespace id
    // can collide with a totally unrelated TV show at that same number. Confirmed live: Ghost in
    // the Shell's real TMDB MOVIE id (9323) is, in the TV namespace, some unrelated 1992 drama
    // miniseries - a perfectly valid-looking /tv/ response for the WRONG show entirely, which
    // then gets confidently searched on anikoto under a name that has nothing to do with the
    // actual title. Japanese origin (original_language/origin_country) is the gate, NOT the
    // Animation genre tag - genre turned out unreliable both ways: Popeye the Sailor (US) IS
    // genuinely tagged Animation, while Devils' Crest (a real, correctly-matched upcoming anime,
    // confirmed live) is tagged only Action & Adventure / Sci-Fi & Fantasy with no Animation id
    // at all, so requiring it rejected a real match. Japanese origin alone correctly separates
    // both of those. Fails back to null (same as a fetch failure) rather than a wrong title.
    const isJapaneseOrigin = anime.original_language === 'ja' ||
        (Array.isArray(anime.origin_country) && anime.origin_country.includes('JP'));
    if (!isJapaneseOrigin) {
        return { title: null, year: null };
    }

    return {
        title: anime.name || anime.original_name || null,
        year: anime.first_air_date ? Number(anime.first_air_date.substring(0, 4)) : null
    };
}

let jikanCounter = 0;
async function jikanGet(pathname) {
    console.log(`[JIKAN START] ${pathname}`);   
    console.log(`[${++jikanCounter}] ${pathname}`);
 
    const url = `https://api.jikan.moe/v4${pathname}`;
    const maxAttempts = 4;
    let delay = 700;

    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
        try {
            await sleep(Math.random() * 500);
            const r = await axios.get(url, {
                timeout: 15000,
                headers: { 'User-Agent': 'LegionSpace/1.0 (+anime-season-groups)' },
                validateStatus: () => true
            });
            console.log("================================");
                console.log("STATUS:", r.status, "PATH:", pathname);
            console.log("PATH:", pathname);
            console.log("STATUS:", r.status);
            console.log("BODY:", JSON.stringify(r.data).slice(0, 500));
            console.log("================================");
            if (r.status >= 200 && r.status < 300) return r.data;
            if (r.status === 429) {
                if (attempt < maxAttempts) {
                    await sleep(delay);
                    delay *= 2;
                    continue;
                }
            }

            if (r.status >= 500) {
                throw new Error(`Jikan ${r.status}`);
            }
            console.log(`[JIKAN ${r.status}] ${pathname}`);

            throw new Error(`Jikan ${r.status}`);
        } catch (err) {
            console.error("========== JIKAN ==========");
            console.error(`[JIKAN ERROR] ${pathname}`);
            console.error(err.message);
            console.error("URL:", url);
            console.error("Attempt:", attempt);
            console.error("Message:", err.message);
            console.error("Code:", err.code);
            console.error("Status:", err.response?.status);
            console.error("Data:", err.response?.data);
            console.error("==========================");

            if (attempt < maxAttempts) {
                await sleep(delay);
                delay *= 2;
                continue;
            }

            throw err;
        }
    }
    throw new Error('Jikan request failed');
}

// Jikan proxy cache (5 min TTL — avoids hammering Jikan on repeated page loads)
const _jikanProxyCache = new Map();
const JIKAN_PROXY_CACHE_TTL = 5 * 60 * 1000;

app.get('/api/jikan', async (req, res) => {
    const jikanPath = req.query.path;
    if (!jikanPath || !String(jikanPath).startsWith('/')) {
        return res.status(400).json({ error: 'Missing or invalid path parameter' });
    }
    const cached = _jikanProxyCache.get(jikanPath);
    if (cached && (Date.now() - cached.t < JIKAN_PROXY_CACHE_TTL)) {
        return res.json(cached.data);
    }
    try {
        const data = await jikanGet(jikanPath);
        _jikanProxyCache.set(jikanPath, { data, t: Date.now() });
        res.json(data);
    } catch (err) {
        console.error("========== JIKAN ERROR ==========");
        console.error("Path:", jikanPath);
        console.error("Message:", err.message);
        console.error("Code:", err.code);
        console.error("Status:", err.response?.status);
        console.error("Response:", err.response?.data);
        console.error(err);
        console.error("=================================");

        res.status(502).json({ error: "Jikan request failed" });
    }
});

function animeScheduleGet(date) {
    return new Promise((resolve, reject) => {
        animeCacheDb.get(
            `SELECT json, cached_at FROM anime_schedule WHERE date = ?`,
            [date],
            (err, row) => {
                if (err) return reject(err);
                if (!row) return resolve(null);

                const now = Date.now();
                animeCacheDb.run(
                    `UPDATE anime_schedule SET last_accessed = ? WHERE date = ?`,
                    [now, date],
                    (updateErr) => {
                        if (updateErr) console.warn('[Anime Schedule] failed to update last_accessed', updateErr.message || updateErr);
                    }
                );

                try {
                    resolve({ data: JSON.parse(row.json), cached_at: row.cached_at });
                } catch (parseErr) {
                    resolve(null);
                }
            }
        );
    });
}

function animeScheduleUpsert(date, day, json) {
    return new Promise((resolve, reject) => {
        const now = Date.now();
        animeCacheDb.run(
            `INSERT INTO anime_schedule (date, day, json, cached_at, last_accessed)
             VALUES (?, ?, ?, ?, ?)
             ON CONFLICT(date) DO UPDATE SET
                 json = excluded.json,
                 cached_at = excluded.cached_at,
                 last_accessed = excluded.last_accessed`,
            [date, day, json, now, now],
            function (err) {
                if (err) return reject(err);
                resolve(this.changes || 0);
            }
        );
    });
}

// Dates are treated as plain calendar days (UTC midnight) so the weekday derived here always
// matches what the frontend computed, regardless of either side's local timezone offset.
function dayNameFromDate(dateStr) {
    const names = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
    return names[new Date(`${dateStr}T00:00:00Z`).getUTCDay()];
}

function isoDateUTC(d) {
    return d.toISOString().slice(0, 10);
}

// Jikan's /schedules/{day} only ever reflects the CURRENT recurring weekly broadcast lineup --
// it cannot answer "what aired on this exact past date" or "what airs on this future date".
// AniList's airingSchedules query is genuinely date-specific (it's a real per-episode airing
// timestamp, not a recurring day-of-week snapshot), so it's what actually makes a real
// multi-week calendar possible instead of an artificial "only the current week" wall.
const ANILIST_AIRING_SCHEDULE_QUERY = `
    query ($page: Int, $from: Int, $to: Int) {
        Page(page: $page, perPage: 50) {
            pageInfo { hasNextPage }
            airingSchedules(airingAt_greater: $from, airingAt_lesser: $to, sort: TIME) {
                airingAt
                episode
                media {
                    id
                    idMal
                    title { romaji english native }
                    coverImage { large extraLarge }
                    averageScore
                    episodes
                    format
                }
            }
        }
    }
`;

function transformAniListAiringSchedule(s) {
    const airDate = new Date(s.airingAt * 1000);
    const hh = String(airDate.getUTCHours()).padStart(2, '0');
    const mm = String(airDate.getUTCMinutes()).padStart(2, '0');
    return {
        title: s.media.title?.romaji || s.media.title?.native || '',
        title_english: s.media.title?.english || null,
        // Kept separately from `title` above (which already falls back to native when romaji is
        // missing, collapsing the distinction) - runFinishedShowScheduleAudit needs all three
        // title forms distinctly available to fuzzy-match against a cached show's own three
        // forms, not just whichever one happened to win that fallback.
        title_native: s.media.title?.native || null,
        images: {
            jpg: {
                image_url: s.media.coverImage?.large || '',
                large_image_url: s.media.coverImage?.extraLarge || s.media.coverImage?.large || ''
            }
        },
        broadcast: { time: `${hh}:${mm}` },
        score: s.media.averageScore ? (s.media.averageScore / 10) : null,
        episodes: s.media.episodes || null,
        idMal: s.media.idMal || null,
        episode: s.episode || null
    };
}

async function fetchAniListDaySchedule(dateIso) {
    const dayStartSec = Math.floor(new Date(`${dateIso}T00:00:00Z`).getTime() / 1000);
    const dayEndSec = dayStartSec + 86400 - 1;

    const response = await axios.post(
        'https://graphql.anilist.co',
        { query: ANILIST_AIRING_SCHEDULE_QUERY, variables: { page: 1, from: dayStartSec, to: dayEndSec } },
        { headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' }, timeout: 15000 }
    );

    const schedules = response.data?.data?.Page?.airingSchedules || [];
    return schedules
        .filter(s => s.media && s.media.format !== 'MOVIE')
        .map(transformAniListAiringSchedule);
}

// Same query as fetchAniListDaySchedule but spanning an arbitrary [startIso, endIso]
// range in as few AniList requests as possible (one per 50-result page instead of
// one per calendar day) -- a 42-day month grid was firing up to 42 parallel AniList
// calls from the same server IP, which is exactly the kind of burst that trips their
// per-IP rate limit. Returns items grouped by the UTC date they air on.
async function fetchAniListRangeScheduleByDate(startIso, endIso) {
    const fromSec = Math.floor(new Date(`${startIso}T00:00:00Z`).getTime() / 1000);
    const toSec = Math.floor(new Date(`${endIso}T00:00:00Z`).getTime() / 1000) + 86400 - 1;

    const grouped = {};
    let page = 1;
    // Safety cap: a 6-week grid during peak simulcast season is realistically a
    // handful of pages; this just guards against an unbounded loop if AniList's
    // pageInfo ever misbehaves.
    while (page <= 20) {
        const response = await axios.post(
            'https://graphql.anilist.co',
            { query: ANILIST_AIRING_SCHEDULE_QUERY, variables: { page, from: fromSec, to: toSec } },
            { headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' }, timeout: 15000 }
        );

        const pageData = response.data?.data?.Page;
        const schedules = pageData?.airingSchedules || [];
        for (const s of schedules) {
            if (!s.media || s.media.format === 'MOVIE') continue;
            const dateIso = new Date(s.airingAt * 1000).toISOString().slice(0, 10);
            if (!grouped[dateIso]) grouped[dateIso] = [];
            grouped[dateIso].push(transformAniListAiringSchedule(s));
        }

        if (!pageData?.pageInfo?.hasNextPage) break;
        page++;
    }

    return grouped;
}

// AniList's own airing-schedule data for a month more than one month out is genuinely
// incomplete right now, not just "sparse" -- new titles keep getting revealed/added to a
// distant month right up until close to their own air date, so caching that month forever
// would freeze it at whatever partial state it happened to be in the first time someone
// browsed there. This month and next month are different: by the time anyone's looking,
// AniList's lineup for them is effectively locked in already, so those (and any past date)
// are safe to cache forever. Everything beyond next month instead gets a weekly refresh so
// newly-revealed titles eventually show up.
function isWithinReliableScheduleWindow(dateIso) {
    const [y, m] = dateIso.split('-').map(Number);
    const now = new Date();
    const thisMonthIndex = now.getUTCFullYear() * 12 + now.getUTCMonth();
    const dateMonthIndex = y * 12 + (m - 1);
    return dateMonthIndex - thisMonthIndex <= 1;
}
const ANIME_SCHEDULE_FAR_FUTURE_REFRESH_MS = 7 * 24 * 60 * 60 * 1000; // 1 week

app.get('/api/anime-schedule', async (req, res) => {
    const dateParam = String(req.query.date || '').trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(dateParam)) {
        return res.status(400).json({ error: 'Missing or invalid date parameter (expected YYYY-MM-DD)' });
    }
    const day = dayNameFromDate(dateParam);

    let cached = null;
    try {
        cached = await animeScheduleGet(dateParam);
    } catch (err) {
        console.warn('[Anime Schedule] cache read failed', err.message || err);
    }

    if (cached && cached.data) {
        if (isWithinReliableScheduleWindow(dateParam)) {
            return res.json(cached.data);
        }
        const ageMs = Date.now() - cached.cached_at;
        if (ageMs < ANIME_SCHEDULE_FAR_FUTURE_REFRESH_MS) {
            return res.json(cached.data);
        }
        console.log(`[Anime Schedule] far-future cache stale for ${dateParam} (${day}): age=${Math.round(ageMs / 1000 / 60)}m, refreshing`);
    }

    try {
        const items = await fetchAniListDaySchedule(dateParam);
        const payload = { data: items };
        await animeScheduleUpsert(dateParam, day, JSON.stringify(payload));
        return res.json(payload);
    } catch (err) {
        console.error('[Anime Schedule] AniList fetch failed', err.message || err);
        if (cached && cached.data) {
            console.warn('[Anime Schedule] returning stale cache after live fetch failure');
            return res.json(cached.data);
        }
        return res.status(502).json({ error: 'AniList schedule fetch failed' });
    }
});

// Same data as /api/anime-schedule but for an entire [start, end] range in one shot --
// used by the calendar's month grid, which used to fire one /api/anime-schedule call
// per visible date (up to 42 in parallel) and was tripping AniList's per-IP rate limit.
// Per-date cache rows are still read/written individually (so a date visited via the
// single-date endpoint elsewhere, e.g. the homepage widget, is shared), only the
// AniList round trip itself is batched for whichever dates in the range are missing
// or stale.
app.get('/api/anime-schedule-range', async (req, res) => {
    const startParam = String(req.query.start || '').trim();
    const endParam = String(req.query.end || '').trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(startParam) || !/^\d{4}-\d{2}-\d{2}$/.test(endParam)) {
        return res.status(400).json({ error: 'start and end are required (expected YYYY-MM-DD)' });
    }

    const dates = [];
    for (let d = new Date(`${startParam}T00:00:00Z`); d.toISOString().slice(0, 10) <= endParam; d.setUTCDate(d.getUTCDate() + 1)) {
        dates.push(d.toISOString().slice(0, 10));
    }
    if (!dates.length || dates.length > 60) {
        return res.status(400).json({ error: 'Invalid or excessive date range' });
    }

    const result = {};
    const missing = [];
    for (const iso of dates) {
        let cached = null;
        try {
            cached = await animeScheduleGet(iso);
        } catch (err) {
            console.warn('[Anime Schedule Range] cache read failed', iso, err.message || err);
        }
        const isFresh = cached && cached.data && (
            isWithinReliableScheduleWindow(iso) || (Date.now() - cached.cached_at) < ANIME_SCHEDULE_FAR_FUTURE_REFRESH_MS
        );
        if (isFresh) {
            // animeScheduleGet's cached.data is the raw parsed row -- {data: items} --
            // not the items array itself (that's what animeScheduleUpsert stores).
            result[iso] = cached.data.data || [];
        } else {
            missing.push(iso);
        }
    }

    if (missing.length) {
        try {
            const grouped = await fetchAniListRangeScheduleByDate(missing[0], missing[missing.length - 1]);
            for (const iso of missing) {
                const items = grouped[iso] || [];
                result[iso] = items;
                try {
                    await animeScheduleUpsert(iso, dayNameFromDate(iso), JSON.stringify({ data: items }));
                } catch (err) {
                    console.warn('[Anime Schedule Range] cache write failed', iso, err.message || err);
                }
            }
        } catch (err) {
            console.error('[Anime Schedule Range] AniList fetch failed', err.message || err);
            for (const iso of missing) {
                if (!(iso in result)) result[iso] = [];
            }
        }
    }

    res.json(result);
});

