    console.log("===== FULL RANKING =====");

    ranked.forEach((r, i) => {
        console.log(
            `${i + 1}. ${r.score} | ${r.result.title} | ${r.result.subOrDub}`
        );
    });

    console.log("========================");
    // const anime = ranked[0].result;
    // console.log(
    //     'ANIME MATCH:',
    //     anime?.title
