// =========================================
//  9b2. ANIME SEASON GROUPS (AniList-backed, Jikan/MAL fallback)
// =========================================

async function aniListGetMediaWithRelations(anilistId) {
    const query = `
        query ($id: Int) {
            Media(id: $id, type: ANIME) {
                id
                idMal
                format
                episodes
                duration
                status
                title { romaji english native }
                startDate { year month day }
                streamingEpisodes { title thumbnail }
                relations {
                    edges {
                        relationType(version: 2)
                        node {
                            id
                            type
                            format
                            episodes
                            duration
                            status
                            title { romaji english native }
                            startDate { year month day }
                        }
                    }
                }
            }
        }
    `;

    const maxAttempts = 3;
    let delay = 500;
    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
        try {
            const response = await axios.post(
                'https://graphql.anilist.co',
                { query, variables: { id: anilistId } },
                { headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' }, timeout: 10000 }
            );
            if (response.data?.errors) {
                throw new Error(`AniList error: ${JSON.stringify(response.data.errors)}`);
            }
            return response.data?.data?.Media || null;
        } catch (err) {
            const status = err.response?.status;
            if (status === 429 && attempt < maxAttempts) {
                await sleep(delay);
                delay *= 2;
                continue;
            }
            throw err;
        }
    }
    throw new Error('AniList request failed');
}

function aniListDateToIso(d) {
    if (!d || !d.year) return null;
    return `${d.year}-${String(d.month || 1).padStart(2, '0')}-${String(d.day || 1).padStart(2, '0')}`;
}

async function buildSeasonGroupsFromAniList(anilistId) {
    const visited = new Set();
    const queue = [Number(anilistId)];
    const metaList = [];
    let failedLookups = 0;
    // A "FINISHED" show never flips back to RELEASING on AniList when a sequel is announced -
    // the sequel shows up as its OWN, separate node in relations, initially NOT_YET_RELEASED,
    // then RELEASING once it actually starts airing. TMDB's own season count only catches up
    // once TMDB itself lists the new season, which can lag well behind AniList already knowing
    // about it - checking this directly is what lets the cache distrust "is_finished" the moment
    // a real sequel is announced, not just once TMDB notices.
    let hasUpcomingSequel = false;
    // The franchise's own title triple, captured from whichever node this walk starts at
    // (the id the caller asked about) rather than metaList[0] -- that entry can be a
    // different season's TV node, or absent entirely if the starting id isn't itself TV
    // format. runFinishedShowScheduleAudit needs one stable identity per franchise to
    // fuzzy-match against the daily airing schedule.
    let baseTitle = null;

    while (queue.length && metaList.length < 8) {
        const id = Number(queue.shift());
        if (!id || visited.has(id)) continue;
        visited.add(id);

        let media;
        try {
            media = await aniListGetMediaWithRelations(id);
        } catch (err) {
            failedLookups++;
            console.warn(`[anime-season-groups] anilist ${id} lookup failed (${err.message}); keeping ${metaList.length} season(s) already resolved`);
            continue;
        }
        if (!media) continue;

        if (id === Number(anilistId) && !baseTitle) {
            baseTitle = {
                english: media.title?.english || null,
                romaji: media.title?.romaji || null,
                native: media.title?.native || null
            };
        }

        // Only TV broadcasts are real "seasons". Sequel/prequel edges also surface recap
        // movies and unreleased tie-in films (e.g. Solo Leveling's "-ReAwakening-" recap and
        // the undated "Beyond the System" movie) — counting those as seasons both invents
        // seasons that don't exist and, since undated entries sort first, shifts the real
        // seasons to the wrong number. Still traverse through them below in case a real
        // season is only reachable via a movie's relations, just don't list them.
        const isTvFormat = ['TV', 'TV_SHORT'].includes(String(media.format || '').toUpperCase());
        if (isTvFormat) {
            metaList.push({
                title: media.title?.english || media.title?.romaji || `Season ${metaList.length + 1}`,
                // Kept separately from `title` above (which prefers English) - MAL's own search
                // results come back in romaji/Japanese, not English, so matching a MAL search
                // hit against a KNOWN sibling needs to compare romaji-to-romaji (see
                // findMalOnlyCourSiblings below). Never sent to the frontend, metaListToGroups
                // only reads `title`/`malId`/etc.
                romajiTitle: media.title?.romaji || null,
                episodesCount: Number(media.episodes || 0),
                airDate: aniListDateToIso(media.startDate),
                // Real per-episode titles/thumbnails when AniList has them (it often does, via
                // crunchyroll/funimation listings), so synthetic seasons don't have to fall back
                // to "Episode N" placeholders with no thumbnail.
                streamingEpisodes: Array.isArray(media.streamingEpisodes) ? media.streamingEpisodes : [],
                // Each split-cour season is its own MAL entry (e.g. "86" is 41457, "86 Part 2"
                // is 48569) with its own local episode numbering. Providers keyed by MAL id
                // (Megaplay) need THIS season's id, not the base show's, or they'll resolve
                // the wrong episode entirely.
                malId: media.idMal || null,
                // TV_SHORT specifically (as opposed to plain TV) is what tags AniList's own
                // 3-4 minute comedy-skit spinoffs (e.g. Re:Zero's "Starting Break Time From
                // Zero") - metaListToGroups uses this to recognize those as bonus content
                // rather than real season episodes, even when their title has no marker to
                // say so either.
                format: media.format || null,
                // Per-episode runtime in minutes - a second, independent signal for the same
                // thing `format` above is for (some of these bonus-shorts entries are still
                // tagged plain "TV" on MAL/AniList rather than "TV_SHORT", so format alone
                // isn't always enough).
                duration: Number.isFinite(media.duration) ? media.duration : null
            });
        }

        const edges = Array.isArray(media.relations?.edges) ? media.relations.edges : [];
        edges.forEach(edge => {
            const rType = String(edge?.relationType || '').toUpperCase();
            if (rType !== 'SEQUEL' && rType !== 'PREQUEL') return;
            const node = edge?.node;
            if (!node || String(node.type || '').toUpperCase() !== 'ANIME') return;
            // Checked regardless of format/traversal below - a SEQUEL sitting at
            // NOT_YET_RELEASED or RELEASING is real evidence more content is coming even if
            // it's e.g. a movie we wouldn't otherwise walk into as a "season".
            if (rType === 'SEQUEL') {
                const nodeStatus = String(node.status || '').toUpperCase();
                if (nodeStatus === 'NOT_YET_RELEASED' || nodeStatus === 'RELEASING') {
                    hasUpcomingSequel = true;
                }
            }
            // Only keep walking through other TV entries. A movie/OVA branch off a real
            // season is very unlikely to lead anywhere but more movies/OVAs, and each
            // extra hop is a full GraphQL round trip we don't need to spend.
            if (!['TV', 'TV_SHORT'].includes(String(node.format || '').toUpperCase())) return;
            const relId = Number(node.id || 0);
            if (relId > 0 && !visited.has(relId)) queue.push(relId);
        });
    }

    return { metaList, failedLookups, hasUpcomingSequel, baseTitle };
}

async function buildSeasonGroupsFromJikan(malId) {
    const visited = new Set();
    const queue = [Number(malId)];
    const metaList = [];
    let failedLookups = 0;

    while (queue.length && metaList.length < 8) {
        const id = Number(queue.shift());
        if (!id || visited.has(id)) continue;
        visited.add(id);

        // One unreachable entry must not discard the seasons already collected.
        // Jikan returns a hard 504/429 for individual anime fairly often (e.g. mal 48569,
        // "86 Part 2"), and letting that throw used to fail the whole request.
        let full;
        try {
            full = await jikanGet(`/anime/${id}/full`);
        } catch (err) {
            failedLookups++;
            console.warn(`[anime-season-groups] mal ${id} lookup failed (${err.message}); keeping ${metaList.length} season(s) already resolved`);
            continue;
        }
        const info = full?.data;
        if (!info) continue;

        // Same reasoning as the AniList walker: only TV entries are real seasons. Jikan's
        // sequel/prequel relations also include recap movies and OVAs.
        if (String(info.type || '').toUpperCase() === 'TV') {
            metaList.push({
                title: info.title || info.title_english || `Season ${metaList.length + 1}`,
                episodesCount: Number(info.episodes || 0),
                airDate: info?.aired?.from ? String(info.aired.from).slice(0, 10) : null,
                malId: info.mal_id || id
            });
        }

        const rels = Array.isArray(info.relations) ? info.relations : [];
        rels.forEach(rel => {
            const rType = String(rel?.relation || '').toLowerCase();
            if (rType !== 'sequel' && rType !== 'prequel') return;
            (rel.entry || []).forEach(ent => {
                if (String(ent?.type || '').toLowerCase() !== 'anime') return;
                const relId = Number(ent?.mal_id || 0);
                if (relId > 0 && !visited.has(relId)) queue.push(relId);
            });
        });
    }

    return { metaList, failedLookups };
}

// Used purely to decide season-groups cache freshness (see ANIME_SEASON_GROUPS_FINISHED_TTL) -
// TMDB's own `status` field ("Ended"/"Canceled" vs "Returning Series"/"In Production") is a
// direct, authoritative "is this show done airing" signal, no guessing needed. number_of_seasons
// doubles as the early-bust trigger the cache already needs.
async function fetchTmdbShowStatus(tmdbId) {
    const res = await axios.get(`${TMDB_BASE_URL}/tv/${tmdbId}`, { params: { api_key: TMDB_API_KEY } });
    const numberOfSeasons = Number.isFinite(res.data?.number_of_seasons) ? res.data.number_of_seasons : undefined;
    const isFinished = res.data?.status === 'Ended' || res.data?.status === 'Canceled';
    const name = res.data?.name || null;
    return { numberOfSeasons, isFinished, name };
}

// TMDB often doesn't split a multi-cour anime into separate seasons at all — it just
// lists one long season covering every cour (e.g. tmdb:100565 "86" has one 23-episode
// season, episodes 1-11 being Part 1 and 12-23 being Part 2, matching AniList's own
// 11+12 split exactly). That real, per-episode TMDB data (titles/dates/thumbnails) is
// almost always better than anything AniList/Jikan can offer at the episode level, so
// use AniList/Jikan only to find the *split point* and slice TMDB's real array by it.
//
// Concatenates EVERY real TMDB season, not just the single largest one - fetching only
// the largest was built for the "one combined TMDB season" case above and silently broke
// for a show that has BOTH a separate TMDB season 1 AND a combined TMDB season 2 (confirmed
// live: Tower of God has TMDB season 1 [13 real eps] and season 2 [26 real eps, itself a
// hidden two-cour split] - fetching only the largest [season 2] and slicing it across all
// THREE metaListToGroups entries handed Season 1's own real 13-episode data to nobody, gave
// group 1 [really Season 1] a wrong slice of season 2's real data instead, and left group 3
// [Workshop Battle] with nothing at all once that one 26-episode array ran out). Concatenating
// every season in season-number order (== chronological order here) means the sequential
// slice in metaListToGroups lines up against the FULL real timeline instead of one arbitrary
// season's worth of it.
async function fetchTmdbRealSeasonEpisodes(tmdbId) {
    const showRes = await axios.get(`${TMDB_BASE_URL}/tv/${tmdbId}`, { params: { api_key: TMDB_API_KEY } });
    const seasons = Array.isArray(showRes.data?.seasons) ? showRes.data.seasons.filter(s => Number(s.season_number) > 0) : [];
    if (seasons.length === 0) return [];
    seasons.sort((a, b) => Number(a.season_number) - Number(b.season_number));

    const allEpisodes = [];
    for (const season of seasons) {
        try {
            const seasonRes = await axios.get(`${TMDB_BASE_URL}/tv/${tmdbId}/season/${season.season_number}`, { params: { api_key: TMDB_API_KEY } });
            const episodes = Array.isArray(seasonRes.data?.episodes) ? seasonRes.data.episodes : [];
            allEpisodes.push(...episodes);
        } catch (err) {
            console.warn(`[TMDB real episodes] season ${season.season_number} fetch failed for tmdb ${tmdbId}:`, err.message);
        }
    }
    return allEpisodes;
}

// --- MAL-only cour-split discovery -------------------------------------------------------
// AniList and Jikan/MAL's own relations graphs are the primary source for cour siblings above,
// but they can genuinely be missing a real split entirely (confirmed live: Tower of God's
// "Workshop Battle" cour is its own MAL entry, id 59989, with NO relations edge pointing to it
// from either AniList's or MAL's side - AniList's own catalog just lists the whole of "Season 2"
// as one combined 26-episode show, and Workshop Battle simply isn't a node in that graph at
// all). MegaPlay (and other providers) still key episodes to that separate MAL id though, so a
// user landing on "Season 2 episode 14" 404s - the site has no idea that id even exists.
//
// This is a last-resort discovery layer: search MAL's own website directly for the base title,
// and use the SAME title-divergence heuristic already proven for anikoto's season-sibling
// grouping to recognize genuine cour siblings among the results, instead of relying on either
// site's relations data at all.
const MAL_SEARCH_UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36';

// In-memory only (process-lifetime, cleared on restart) - the OUTER /api/anime-season-groups
// cache (disk-backed, long TTL for finished shows) already protects repeat lookups of the same
// tmdbId. These protect a NARROWER but real risk: the burst pattern WITHIN one fresh season-
// groups computation - a single title with several MAL search candidates (confirmed live:
// Overlord's Ple Ple Pleiades entries) fires one search plus several detail-page fetches to MAL
// in a row, which is exactly the pattern that gets a raw scraper's IP flagged/CAPTCHA'd, unlike
// one request every so often. Long TTLs are safe either way - a MAL search's result SET for a
// given franchise name, and any single anime's own episode count/air date/type/English title,
// are all essentially static once determined; these are correctness backstops, not an actual
// expectation that MAL's answer will change.
const _malSearchCache = new Map(); // query (lowercased) -> { results, cachedAt }
const MAL_SEARCH_CACHE_TTL = 14 * 24 * 60 * 60 * 1000; // 14 days
const _malDetailsCache = new Map(); // malId -> { details, cachedAt }
const MAL_DETAILS_CACHE_TTL = 30 * 24 * 60 * 60 * 1000; // 30 days

async function searchMalWebsiteUncached(query) {
    const res = await axios.get('https://myanimelist.net/anime.php', {
        params: { q: query, cat: 'anime' },
        headers: { 'User-Agent': MAL_SEARCH_UA },
        timeout: 15000
    });
    const $ = cheerio.load(res.data);
    const results = [];
    const seen = new Set();
    $('a.hoverinfo_trigger').each((i, el) => {
        const href = $(el).attr('href') || '';
        const m = href.match(/\/anime\/(\d+)\//);
        const title = $(el).find('strong').text().trim() || $(el).text().trim();
        if (!m || !title) return;
        const malId = parseInt(m[1], 10);
        if (seen.has(malId)) return;
        seen.add(malId);
        results.push({ malId, title });
    });
    return results;
}

async function searchMalWebsite(query) {
    const key = String(query || '').toLowerCase().trim();
    if (!key) return [];
    const cached = _malSearchCache.get(key);
    if (cached && (Date.now() - cached.cachedAt) < MAL_SEARCH_CACHE_TTL) return cached.results;
    const results = await searchMalWebsiteUncached(query);
    _malSearchCache.set(key, { results, cachedAt: Date.now() });
    return results;
}

// Scrapes a MAL anime page directly for its episode count and air date - the equivalent of
// what Jikan's /anime/{id} would normally give, but self-contained (no dependency on Jikan's
// uptime, which has been unreliable) since this only needs two fields, both present in MAL's
// own sidebar on every anime page.
async function fetchMalAnimeDetailsUncached(malId) {
    const res = await axios.get(`https://myanimelist.net/anime/${malId}`, {
        headers: { 'User-Agent': MAL_SEARCH_UA },
        timeout: 15000
    });
    const $ = cheerio.load(res.data);
    let episodes = null;
    let airDate = null;
    let titleEn = null;
    let type = null;
    let status = null;
    let duration = null;
    // The page's own <h1> is MAL's main/native title (usually romaji) - separate from the
    // "English:" sidebar field below. Needed for scrapeMalRelations/buildSeasonGroupsFromMal
    // Relations, which push this straight into the same romajiTitle field
    // buildSeasonGroupsFromAniList already populates.
    const titleNative = $('h1.title-name').first().text().trim() || $('h1').first().text().trim() || null;
    // og:image is the same poster CDN URL Jikan's images.jpg.large_image_url would have given -
    // needed by buildSeasonCardsFromMalRelations (season-cards' own cover art, Jikan-free path).
    const coverImage = $('meta[property="og:image"]').attr('content') || null;
    $('.spaceit_pad, .spaceit').each((i, el) => {
        const text = $(el).text().trim();
        const epMatch = text.match(/^Episodes:\s*(\d+)/i);
        if (epMatch) episodes = parseInt(epMatch[1], 10);
        const airMatch = text.match(/^Aired:\s*([A-Za-z]+\s+\d{1,2},\s*\d{4})/);
        if (airMatch) {
            const d = new Date(airMatch[1]);
            if (!Number.isNaN(d.getTime())) airDate = d.toISOString().slice(0, 10);
        }
        // MAL's sidebar carries an explicit "English:" alternative-title field distinct from
        // the page's own (often romaji/native) main title - needed because anikoto's own
        // catalog is titled in English, not romaji (confirmed live: matching a MAL-only
        // sibling's romaji title "Kami no Tou: Koubou-sen" against anikoto's candidates, whose
        // titles are "Tower of God Season 2: Workshop Battle" etc., scored near-zero
        // similarity across the board and picked a completely unrelated show).
        const enMatch = text.match(/^English:\s*(.+)$/i);
        if (enMatch) titleEn = enMatch[1].trim();
        // "Type: TV" vs "ONA"/"Special"/"Movie" - needed to reject spin-off shorts sharing the
        // base franchise name (confirmed live: Overlord's "Ple Ple Pleiades" chibi-comedy shorts
        // are type ONA, 2 minutes/episode, but their titles diverge from "Overlord" in exactly
        // the "base + trailing number" shape the title-divergence check already accepts for
        // genuine season siblings like "Overlord II"/"III"/"IV" - title matching alone can't
        // tell these apart, only the real catalog type can).
        const typeMatch = text.match(/^Type:\s*([A-Za-z]+)/i);
        if (typeMatch) type = typeMatch[1].trim().toUpperCase();
        // "Status: Finished Airing" / "Currently Airing" / "Not yet aired" - same 3-way signal
        // Jikan's own `status` field gives, needed by buildSeasonCardsFromMalRelations to detect
        // an upcoming/ongoing season the same way fetchJikanSeasonCardsChain already does.
        const statusMatch = text.match(/^Status:\s*(.+)$/i);
        if (statusMatch) status = statusMatch[1].trim();
        // "Duration: 3 min. per ep." / "Duration: 24 min." - same signal AniList's own
        // `duration` field gives, needed alongside `type` to catch bonus-shorts spinoffs
        // MAL itself still tags plain "TV" (confirmed live: Re:Zero's "Starting Break Time
        // From Zero" comedy shorts pass the type==='TV' check above but are 3 min/ep, not a
        // real season's ~24 min episodes).
        const durationMatch = text.match(/^Duration:\s*(\d+)\s*min/i);
        if (durationMatch) duration = parseInt(durationMatch[1], 10);
    });
    return { episodes, airDate, titleEn, type, titleNative, coverImage, status, duration };
}

async function fetchMalAnimeDetails(malId) {
    const cached = _malDetailsCache.get(malId);
    if (cached && (Date.now() - cached.cachedAt) < MAL_DETAILS_CACHE_TTL) return cached.details;
    const details = await fetchMalAnimeDetailsUncached(malId);
    _malDetailsCache.set(malId, { details, cachedAt: Date.now() });
    return details;
}

// --- MAL relations scrape (Jikan replacement) --------------------------------------------
// Jikan's own "sunset" date is under a month out at the time this was written, and it's been
// unreliable well before that (504/429 on individual anime lookups all session) - this scrapes
// the exact same "Related Anime" data directly off MAL's own page instead of going through
// Jikan's API layer at all, so buildSeasonGroupsFromMalRelations below has no Jikan dependency.
// Every related entry sits in a `.entry` block under `.related-entries`, each with a
// `.content .relation` line ("Sequel", "Prequel", "Adaptation", ...) and a `.content .title a`
// link - manga/light-novel/other non-anime relations are filtered out by requiring the link's
// own href to be an /anime/ URL, not by trying to parse the relation type text's parenthetical.
const _malRelationsCache = new Map(); // malId -> { relations, cachedAt }
const MAL_RELATIONS_CACHE_TTL = 30 * 24 * 60 * 60 * 1000; // 30 days - same reasoning as MAL_DETAILS_CACHE_TTL, a show's own relations essentially never change once established

async function scrapeMalRelationsUncached(malId) {
    const res = await axios.get(`https://myanimelist.net/anime/${malId}`, {
        headers: { 'User-Agent': MAL_SEARCH_UA },
        timeout: 15000
    });
    const $ = cheerio.load(res.data);
    const relations = [];
    $('.related-entries .entry').each((i, el) => {
        const relationText = $(el).find('.content .relation').first().text().trim();
        const relationType = relationText.split('(')[0].trim().toUpperCase();
        const link = $(el).find('.content .title a').first();
        const href = link.attr('href') || '';
        const title = link.text().trim();
        const animeMatch = href.match(/\/anime\/(\d+)\//);
        if (!animeMatch || !title) return; // not an anime relation (manga/LN/etc.) - skip
        relations.push({ relationType, malId: parseInt(animeMatch[1], 10), title });
    });
    // A side-story/spin-off (confirmed live: Sword Oratoria, a DanMachi spin-off TMDB bundles
    // into the SAME tv entry as the main show's own seasons) often has NO Sequel/Prequel edges
    // at all - its own Related Entries section is just manga/LN adaptations. Its real season
    // chain (matching TMDB's own bundling) lives on the PARENT series instead, which MAL surfaces
    // in a completely separate "Parent Story:" table, not part of .related-entries at all.
    // Captured here as its own relationType so callers can choose to fall back into it only when
    // Sequel/Prequel came up empty, rather than always walking into an unrelated parent chain.
    $('.entries-table tr').each((i, row) => {
        const label = $(row).find('td').first().text().trim();
        if (!/^Parent Story:?$/i.test(label)) return;
        $(row).find('td .entries li a').each((j, a) => {
            const href = $(a).attr('href') || '';
            const title = $(a).text().trim();
            const animeMatch = href.match(/\/anime\/(\d+)\//);
            if (!animeMatch || !title) return;
            relations.push({ relationType: 'PARENT_STORY', malId: parseInt(animeMatch[1], 10), title });
        });
    });
    return relations;
}

async function scrapeMalRelations(malId) {
    const cached = _malRelationsCache.get(malId);
    if (cached && (Date.now() - cached.cachedAt) < MAL_RELATIONS_CACHE_TTL) return cached.relations;
    const relations = await scrapeMalRelationsUncached(malId);
    _malRelationsCache.set(malId, { relations, cachedAt: Date.now() });
    return relations;
}

// Direct MAL replacement for buildSeasonGroupsFromJikan above (kept intact, not deleted, in
// case this ever needs reverting) - same BFS-over-SEQUEL/PREQUEL-relations shape, just sourced
// from scrapeMalRelations/fetchMalAnimeDetails (both plain MAL scrapes) instead of jikanGet.
async function buildSeasonGroupsFromMalRelations(malId) {
    const visited = new Set();
    const queue = [Number(malId)];
    const metaList = [];
    let failedLookups = 0;

    while (queue.length && metaList.length < 8) {
        const id = Number(queue.shift());
        if (!id || visited.has(id)) continue;
        visited.add(id);

        let details;
        try {
            details = await fetchMalAnimeDetails(id);
        } catch (err) {
            failedLookups++;
            console.warn(`[anime-season-groups] mal ${id} detail lookup failed (${err.message}); keeping ${metaList.length} season(s) already resolved`);
            continue;
        }

        // Same reasoning as the AniList/Jikan walkers: only TV entries are real seasons.
        // Duration check same as findMalOnlyCourSiblings' own - MAL still tags some
        // bonus-shorts spinoffs plain "TV" (Re:Zero's "Starting Break Time From Zero"), the
        // type check alone won't catch those.
        const isBonusShort = Number.isFinite(details.duration) && details.duration > 0 && details.duration < 10;
        if (details.type === 'TV' && !isBonusShort) {
            metaList.push({
                title: details.titleEn || details.titleNative || `Season ${metaList.length + 1}`,
                romajiTitle: details.titleNative || null,
                episodesCount: Number(details.episodes || 0),
                airDate: details.airDate || null,
                malId: id,
                duration: details.duration || null
            });
        } else if (details.type === 'TV' && isBonusShort) {
            logAnikotoDebug(`[anime-season-groups] mal ${id}: rejecting short-duration TV entry "${details.titleEn || details.titleNative}" (${details.duration} min/ep), likely a bonus/shorts spinoff`);
        }

        let relations;
        try {
            relations = await scrapeMalRelations(id);
        } catch (err) {
            failedLookups++;
            console.warn(`[anime-season-groups] mal ${id} relations lookup failed (${err.message})`);
            continue;
        }
        relations.forEach(rel => {
            if (rel.relationType !== 'SEQUEL' && rel.relationType !== 'PREQUEL') return;
            if (rel.malId > 0 && !visited.has(rel.malId)) queue.push(rel.malId);
        });
    }

    return { metaList, failedLookups };
}

// Season-cards' own MAL-direct fallback - same BFS-over-SEQUEL/PREQUEL shape as
// buildSeasonGroupsFromMalRelations just above, sourced from the same two plain MAL scrapes
// (scrapeMalRelations/fetchMalAnimeDetails), just returning the season-cards shape (idMal/
// title/coverImage/airDate/status) instead of metaList's episode-group shape. This replaces
// fetchJikanSeasonCardsChain as the primary AniList fallback: confirmed live that Jikan can
// sustain a 504 on one specific mid-chain node across all 4 of its own retries (Attack on
// Titan's Season 2 entry, mal 25777) while MAL's own page for that same id loads fine - Jikan
// is also headed for its own sunset, so it's demoted to a last-resort-of-the-last-resort below
// rather than removed outright.
async function buildSeasonCardsFromMalRelations(malId, tmdbSeasonCount) {
    const visited = new Set();
    const queue = [Number(malId)];
    const found = []; // { idMal, title, coverImage, airDate, status }
    const parentStoryIds = new Set();

    while (queue.length && found.length < 8) {
        const id = Number(queue.shift());
        if (!id || visited.has(id)) continue;
        visited.add(id);

        let details;
        try {
            details = await fetchMalAnimeDetails(id);
        } catch (err) {
            continue; // one unreachable MAL entry shouldn't drop the rest of this chain
        }

        if (details.type === 'TV') {
            const statusLower = String(details.status || '').toLowerCase();
            found.push({
                idMal: id,
                title: details.titleEn || details.titleNative || null,
                coverImage: details.coverImage || null,
                airDate: details.airDate || null,
                status: statusLower.includes('currently airing') ? 'RELEASING'
                    : statusLower.includes('not yet') ? 'NOT_YET_RELEASED' : 'FINISHED'
            });
        }

        let relations;
        try {
            relations = await scrapeMalRelations(id);
        } catch (err) {
            continue;
        }
        relations.forEach(rel => {
            if (rel.relationType === 'PARENT_STORY') {
                if (rel.malId > 0) parentStoryIds.add(rel.malId);
                return;
            }
            if (rel.relationType !== 'SEQUEL' && rel.relationType !== 'PREQUEL') return;
            if (rel.malId > 0 && !visited.has(rel.malId)) queue.push(rel.malId);
        });
    }

    // A side-story/spin-off (confirmed live: Sword Oratoria, a DanMachi spin-off) can have zero
    // Sequel/Prequel edges of its own - Related Entries is just manga/LN adaptations - which
    // left found holding only the seed itself. This fallback exists for the case where TMDB
    // genuinely bundles the parent's multi-season structure into the SAME tv entry as the
    // spin-off - but Sword Oratoria itself is proof that's not universal: TMDB lists it as its
    // own standalone single-season entry, so walking into the parent's ENTIRE sequel chain (II/
    // III/IV/etc, each a real season of a DIFFERENT show) just relabels those as if they were
    // more seasons of the spin-off. tmdbSeasonCount > 1 is the actual evidence of bundling this
    // fallback needs - without it, "found nothing of its own" more often just means "this really
    // is a standalone side-story," not "TMDB folded it into the parent."
    if (found.length <= 1 && parentStoryIds.size && Number(tmdbSeasonCount) > 1) {
        const parentQueue = Array.from(parentStoryIds).filter(id => !visited.has(id));
        while (parentQueue.length && found.length < 8) {
            const id = Number(parentQueue.shift());
            if (!id || visited.has(id)) continue;
            visited.add(id);

            let details;
            try {
                details = await fetchMalAnimeDetails(id);
            } catch (err) {
                continue;
            }
            if (details.type === 'TV') {
                const statusLower = String(details.status || '').toLowerCase();
                found.push({
                    idMal: id,
                    title: details.titleEn || details.titleNative || null,
                    coverImage: details.coverImage || null,
                    airDate: details.airDate || null,
                    status: statusLower.includes('currently airing') ? 'RELEASING'
                        : statusLower.includes('not yet') ? 'NOT_YET_RELEASED' : 'FINISHED'
                });
            }

            let relations;
            try {
                relations = await scrapeMalRelations(id);
            } catch (err) {
                continue;
            }
            relations.forEach(rel => {
                if (rel.relationType !== 'SEQUEL' && rel.relationType !== 'PREQUEL') return;
                if (rel.malId > 0 && !visited.has(rel.malId)) parentQueue.push(rel.malId);
            });
        }
    }

    return found;
}

// --- Health check log file ---------------------------------------------------------------
// The terminal gets spammed with real request logs constantly - a health check result can
// easily scroll off screen and out of scrollback before anyone notices it failed. Every health
// check below (Kino's included) now ALSO appends to this one durable, append-only file, so
// "did a check fail overnight" is always answerable by opening one file instead of hoping the
// terminal buffer still has it.
const HEALTH_STATUS_LOG_PATH = path.join(__dirname, 'Health_Status_checker VM.txt');
function logHealthStatus(line) {
    const stamped = `[${new Date().toISOString()}] ${line}`;
    console.log(stamped);
    fs.appendFile(HEALTH_STATUS_LOG_PATH, stamped + '\n', (err) => {
        if (err) console.error('[HealthLog] Failed to write to Health_Status_checker VM.txt:', err.message);
    });
}

// --- MAL health check -------------------------------------------------------------------
// Same reasoning as the Kino health check above: MAL can change its own markup, start
// rate-limiting/blocking us, or go down, with nothing alerting us until a title's season
// discovery quietly stops finding real data. Runs the three raw scrapes (search, detail page,
// relations) against a fixed, never-changing reference title on a timer, and checks the ACTUAL
// PARSED VALUES against known-correct answers, not just "didn't throw" - a markup change often
// makes cheerio's selectors silently return null/empty instead of erroring, which a bare
// try/catch would report as "healthy" right up until every real lookup started coming back
// empty too.
//
// Attack on Titan (not Cowboy Bebop - tried that first, reverted) specifically: confirmed live
// that Cowboy Bebop's own MAL page genuinely lists ZERO anime-type relations (only two manga
// adaptations), which made the relations assertion below fail against a perfectly healthy
// scraper. AoT's season 1 entry has a real, stable Sequel relation to Season 2 - a much better
// reference for exercising all three scrapes meaningfully.
const MAL_HEALTH_CHECK_MAL_ID = 16498; // Attack on Titan (Season 1) - finished franchise, 25 episodes and its Sequel relation will never change
const MAL_HEALTH_CHECK_TITLE = 'Attack on Titan';
const MAL_HEALTH_CHECK_RELATED_MAL_ID = 25777; // Attack on Titan Season 2 - the known Sequel relation
const MAL_HEALTH_CHECK_INTERVAL_MS = 30 * 60 * 1000; // less frequent than Kino's 10min - MAL's markup doesn't shift on the same short, unpredictable timescale vidsrcme's fingerprint check did
let malHealthCheckRunning = false;

async function runMalHealthCheck() {
    if (malHealthCheckRunning) return; // don't overlap if a run somehow takes a while
    malHealthCheckRunning = true;
    const startedAt = Date.now();
    // Deliberately calls the *Uncached variants directly - this must exercise the real scrape
    // every time, not report "healthy" off a stale cached success from hours/days ago.
    const failures = [];
    try {
        const results = await searchMalWebsiteUncached(MAL_HEALTH_CHECK_TITLE);
        if (!results.some(r => r.malId === MAL_HEALTH_CHECK_MAL_ID)) {
            failures.push(`search: expected mal ${MAL_HEALTH_CHECK_MAL_ID} in results for "${MAL_HEALTH_CHECK_TITLE}", got ${results.length} result(s) without it`);
        }
    } catch (err) {
        failures.push(`search threw: ${err.message}`);
    }
    try {
        const details = await fetchMalAnimeDetailsUncached(MAL_HEALTH_CHECK_MAL_ID);
        if (details.episodes !== 25) failures.push(`details: expected 25 episodes, got ${details.episodes}`);
        if (details.type !== 'TV') failures.push(`details: expected type TV, got ${details.type}`);
        if (!details.titleNative || !details.titleNative.toLowerCase().includes('shingeki')) {
            failures.push(`details: expected titleNative to contain "shingeki", got "${details.titleNative}"`);
        }
    } catch (err) {
        failures.push(`details threw: ${err.message}`);
    }
    try {
        const relations = await scrapeMalRelationsUncached(MAL_HEALTH_CHECK_MAL_ID);
        const hasSequel = relations.some(r => r.relationType === 'SEQUEL' && r.malId === MAL_HEALTH_CHECK_RELATED_MAL_ID);
        if (!hasSequel) {
            failures.push(`relations: expected a SEQUEL relation to mal ${MAL_HEALTH_CHECK_RELATED_MAL_ID}, got ${JSON.stringify(relations)}`);
        }
    } catch (err) {
        failures.push(`relations threw: ${err.message}`);
    }

    if (failures.length === 0) {
        logHealthStatus(`[MAL Health] OK (${Date.now() - startedAt}ms)`);
    } else {
        const banner = '!'.repeat(70);
        logHealthStatus(`\n${banner}\n⚠️  ⚠️  ⚠️   MAL SCRAPING IS BROKEN   ⚠️  ⚠️  ⚠️\n${banner}`);
        failures.forEach(f => logHealthStatus(`[MAL Health] ${f}`));
        logHealthStatus(`${banner}\n`);
    }
    malHealthCheckRunning = false;
}

// anchorRomajiTitle should be a KNOWN sibling's own romaji/native title (matching the language
// MAL's search results come back in - an English query still works for the search itself, MAL's
// engine is alias-aware, but the RESULT titles need a same-language anchor to compare against,
// same lesson learned fixing KAA's own title/otherName mismatch earlier). excludeMalIds skips
// entries already known via AniList/Jikan, so this only ever ADDS genuinely new siblings.
async function findMalOnlyCourSiblings(searchQuery, anchorRomajiTitle, excludeMalIds) {
    if (!searchQuery || !anchorRomajiTitle) return [];
    let results;
    try {
        results = await searchMalWebsite(searchQuery);
    } catch (err) {
        logAnikotoDebug(`[MAL siblings] search failed for "${searchQuery}"`, { error: err.message || String(err) });
        return [];
    }

    const exclude = new Set((excludeMalIds || []).filter(Number.isFinite));
    const candidates = results.filter(r =>
        Number.isFinite(r.malId) && !exclude.has(r.malId) && isAnikotoVariantDivergence(anchorRomajiTitle, r.title)
    );
    if (!candidates.length) return [];

    const siblings = [];
    for (const c of candidates) {
        try {
            const details = await fetchMalAnimeDetails(c.malId);
            // Same recap/short exclusion floor already proven on the KAA native lookup - a
            // real cour is rarely under 4 episodes, a music video/recap short usually is.
            if (!Number.isFinite(details.episodes) || details.episodes < 4) continue;
            // Only accept genuine TV seasons - title-divergence matching alone can't tell a
            // real season sibling ("Overlord II") apart from a same-franchise spin-off short
            // ("Overlord: Ple Ple Pleiades 2", type ONA) when both fit the "base + trailing
            // number" shape. MAL's own catalog type is the one signal that actually
            // distinguishes them (confirmed live: Ple Ple Pleiades entries are ONA, not TV).
            if (details.type && details.type !== 'TV') {
                logAnikotoDebug(`[MAL siblings] rejecting non-TV candidate "${c.title}" (mal ${c.malId}, type ${details.type})`);
                continue;
            }
            // MAL itself still tags some bonus-shorts spinoffs plain "TV" (confirmed live:
            // Re:Zero's "Starting Break Time From Zero" comedy shorts) - the type check above
            // alone doesn't catch those, but their per-episode runtime does.
            if (Number.isFinite(details.duration) && details.duration > 0 && details.duration < 10) {
                logAnikotoDebug(`[MAL siblings] rejecting short-duration candidate "${c.title}" (mal ${c.malId}, ${details.duration} min/ep)`);
                continue;
            }
            // Prefer the English title for the group's primary display/matching title, same
            // convention buildSeasonGroupsFromAniList already follows (media.title?.english ||
            // media.title?.romaji) - keeps every downstream consumer (Neko/anikoto's own
            // English-titled catalog, the frontend UI) working the same way regardless of
            // whether a season came from AniList or this MAL-only fallback. The raw MAL/romaji
            // title is kept as titleNative for KAA, whose own catalog IS titled in
            // romaji/native form.
            siblings.push({
                malId: c.malId,
                title: details.titleEn || c.title,
                titleNative: c.title,
                episodesCount: details.episodes,
                airDate: details.airDate,
                duration: details.duration
            });
        } catch (err) {
            logAnikotoDebug(`[MAL siblings] detail fetch failed for mal ${c.malId}`, { error: err.message || String(err) });
        }
    }
    return siblings;
}

function metaListToGroups(metaList, tmdbEpisodes = []) {
    // Missing/unparseable dates sort last, not to epoch-0 first — an unannounced season
    // has no date yet, but it still airs after everything that already has one.
    const sortKey = (d) => { const t = Date.parse(d || ''); return Number.isNaN(t) ? Infinity : t; };
    const sorted = [...metaList].sort((a, b) => sortKey(a.airDate) - sortKey(b.airDate));

    // AniList sometimes duplicates one season's streamingEpisodes listing onto a sibling
    // season's entry (confirmed live: "86" and "86 Part 2" both return the identical
    // 11-episode Crunchyroll list). This is only used as a last-resort fallback now (real
    // TMDB data wins whenever available), but still worth guarding against.
    const seenEpisodeLists = new Set();
    sorted.forEach(m => {
        const key = JSON.stringify((m.streamingEpisodes || []).map(e => e.title));
        if (key === '[]') return;
        if (seenEpisodeLists.has(key)) {
            m.streamingEpisodes = [];
        } else {
            seenEpisodeLists.add(key);
        }
    });

    let tmdbOffset = 0;
    const perEntry = sorted.map(m => {
        const streaming = Array.isArray(m.streamingEpisodes) ? m.streamingEpisodes : [];
        // AniList/Jikan's `episodes` count is null/0 for a currently-airing season
        // until MAL/AniList staff confirm the final total once it finishes -- a
        // near-universal behavior for anything still airing weekly, not an error.
        // Trusting that blindly (Math.max(1, ...) was the only other floor)
        // collapsed an already-partially-aired, ongoing season down to a
        // single-episode placeholder even though several real episodes existed.
        // AniList's streamingEpisodes listing tracks what's actually aired in
        // closer to real time, so use whichever signal is larger.
        const total = Math.max(1, Number(m.episodesCount || 0), streaming.length);
        const tmdbSlice = tmdbEpisodes.slice(tmdbOffset, tmdbOffset + total);
        tmdbOffset += total;

        // Every episode carries its own OWN part's malId/title alongside the merge that
        // happens below - a "Season 2" that's really "Episode 0 special" + "Part 1" + "Part
        // 2" under MAL/AniList (three separate malIds, each with its own local 1-based
        // episode numbering) still needs each individual episode routed to the malId it
        // actually lives under, not whichever part happened to be first. `episode_number`
        // gets renumbered continuously across the merged season further down; `localEpisodeNumber`
        // keeps the number this part's own provider (KAA/Neko/Anikoto) actually expects.
        const romajiTitle = m.romajiTitle || m.title || null;
        const episodes = Array.from({ length: total }, (_, i) => {
            const tmdbEp = tmdbSlice[i];
            const base = {
                episode_number: i + 1,
                localEpisodeNumber: i + 1,
                malId: m.malId || null,
                sourceTitle: m.title || null,
                romajiTitle
            };
            if (tmdbEp) {
                return {
                    ...base,
                    name: tmdbEp.name || `Episode ${i + 1}`,
                    air_date: tmdbEp.air_date || null,
                    still_path: tmdbEp.still_path || null
                };
            }
            // No real TMDB data for this slot (counts didn't line up, or TMDB is short).
            // Fall back to AniList's streaming listing, then a plain placeholder.
            const real = streaming[i];
            // AniList titles these like "Episode 1 - Undertaker"; the frontend already
            // prefixes "S{n} · " on its own, so strip the leading "Episode N - " to avoid
            // "S2 · Episode 1 - Undertaker" doubling up.
            const realName = real?.title ? real.title.replace(/^Episode\s*\d+\s*[-:]\s*/i, '').trim() : '';
            return {
                ...base,
                name: realName || `Episode ${i + 1}`,
                air_date: null,
                still_path: real?.thumbnail || null
            };
        });

        // Same title-parsing rule used by the season CARDS list (buildSeasonCardsFromMalRelations)
        // - reused here so the episode list agrees with it. Without this, a split-cour "Part 2" or
        // a pre-season recap entry ("Season 2 - Episode 0 ...") each became their own numbered
        // "season" instead of being folded into the real season they actually belong to (confirmed
        // live: Jobless Reincarnation's 6 raw MAL/AniList entries collapse to 3 real seasons this
        // way, matching MAL/AniList's own canonical season count instead of TMDB's over-split one).
        const parsed = parseAnimeTitle(m.title || '');
        return { parsed, member: m, episodes };
    });

    const groupsBySeason = new Map();
    const seasonOrder = [];
    // Tracks the season currently being built, and the title of whichever entry most
    // recently landed in it - both reset to null and rebuilt as entries are walked in
    // air-date order (see below for how each branch uses them).
    let currentSeason = null;
    let currentSeasonLabel = null;
    perEntry.forEach(({ parsed, member, episodes }) => {
        let trueSeason;
        if (parsed.isAlternateSpinoff) {
            // A same-universe side story with its own separate watch page (e.g. "Sword Art
            // Online Alternative: Gun Gale Online II") - AniList's relations graph still
            // surfaces it as a SEQUEL/PREQUEL of the main show, and its own "II" would
            // otherwise get misread as this show's season 2. Drop outright.
            logAnikotoDebug(`[anime-season-groups] dropping "${member.title}" (mal ${member.malId}) - looks like a same-universe spinoff with its own separate entry, not a real season`);
            return;
        }
        if (parsed.hasSeasonMarker) {
            // An explicit season number/ordinal/roman numeral/"Final Season" in the title -
            // trust it directly, same as before.
            trueSeason = parsed.season;
        } else if (parsed.hasPartMarker) {
            // "Part 2"/"Cour 2" with no season number of its own always continues whichever
            // season is currently open, never the hardcoded season-1 default.
            trueSeason = currentSeason !== null ? currentSeason : 1;
        } else if (member.format === 'TV_SHORT' || (Number.isFinite(member.duration) && member.duration > 0 && member.duration < 10)) {
            // No season/part marker AND either a comedy-shorts/bonus format or a sub-10-minute
            // runtime (e.g. Re:Zero's "Starting Break Time From Zero", 3 min/ep - some paths
            // only have one of these two signals available, so both are checked) - almost
            // certainly unrelated bonus content, not real season episodes. Drop rather than
            // let it default into season 1 or merge into whatever season is open.
            logAnikotoDebug(`[anime-season-groups] dropping "${member.title}" (mal ${member.malId}) - short-form/no season marker, likely a bonus/shorts spinoff`);
            return;
        } else if (currentSeason === null) {
            // Genuine root entry: no season/part marker, and nothing established yet - this
            // is what a real opening season's own title usually looks like.
            trueSeason = 1;
        } else if (currentSeasonLabel && (() => {
            const a = normalizeAnimeTitle(member.title);
            const b = normalizeAnimeTitle(currentSeasonLabel);
            if (!a || !b) return false;
            const contained = a.includes(b) ? b : (b.includes(a) ? a : null);
            // The shorter (contained) string needs to be specific enough to mean something -
            // a bare one-word franchise name like "Bleach" is trivially a substring of every
            // sequel too ("Bleach: Thousand-Year Blood War"), which would wrongly fold a
            // whole new season into season 1 forever. Requiring a few real words makes this
            // only fire for genuinely matching arc names (e.g. "Sword Art Online:
            // Alicization" inside "...Alicization - War of Underworld").
            return !!contained && contained.split(' ').filter(Boolean).length >= 3;
        })()) {
            // No season/part marker, but this title visibly builds on the currently open
            // season's own title (e.g. "Alicization" -> "Alicization - War of Underworld" -
            // same base name, no number needed to tell they're the same season/arc).
            trueSeason = currentSeason;
        } else {
            // No season/part marker, real TV/OVA format, and no visible relation to the
            // currently open season's title - a genuinely new season that just doesn't
            // number itself in its own title (e.g. SAO's "Alicization" itself, which comes
            // right after "Sword Art Online II" with nothing in common but the base
            // franchise name already stripped out above).
            trueSeason = currentSeason + 1;
        }
        currentSeason = trueSeason;
        currentSeasonLabel = member.title;
        if (!groupsBySeason.has(trueSeason)) {
            groupsBySeason.set(trueSeason, {
                seasonNumber: trueSeason,
                label: member.title || `Season ${trueSeason}`,
                // English title above (`label`) is what Neko/anikoto's own English-titled catalog
                // needs to match against; KAA's catalog is titled in romaji/native form instead, so
                // its own override uses this field specifically. Falls back to `label` itself for
                // AniList-sourced entries that never had a distinct romaji field captured, same as
                // before this field existed. Kept as the season-level default for callers that
                // haven't picked a specific episode yet - each episode's own romajiTitle/malId
                // above is what actually matters once one has.
                romajiTitle: member.romajiTitle || member.title || `Season ${trueSeason}`,
                malId: member.malId || null,
                episodes: []
            });
            seasonOrder.push(trueSeason);
        }
        groupsBySeason.get(trueSeason).episodes.push(...episodes);
    });

    // Renumber continuously within each merged season (Part 1 episodes 1..N, Part 2 picks up
    // at N+1, etc.) so the episode list itself reads like one normal season - `localEpisodeNumber`
    // set above is untouched and still holds the number each episode's own provider expects.
    seasonOrder.forEach(sn => {
        groupsBySeason.get(sn).episodes.forEach((ep, i) => { ep.episode_number = i + 1; });
    });

    return seasonOrder
        .map(sn => groupsBySeason.get(sn))
        .sort((a, b) => a.seasonNumber - b.seasonNumber);
}

// --- animefillerlist.com filler/canon status --------------------------------------------
// Jikan's own `filler` field is a plain boolean (confirmed against its OpenAPI schema) --
// MAL doesn't track the "Mixed Canon/Filler" or "Anime Canon" distinction at all, that's
// animefillerlist-specific granularity, so this is the only real source for the full
// 4-category system (Manga Canon / Filler / Mixed Canon-Filler / Anime Canon).
const ANIMEFILLERLIST_UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36';
let animeFillerListDirectoryCache = null; // { entries: [{slug,title}], fetchedAt }
const ANIMEFILLERLIST_DIRECTORY_TTL_MS = 24 * 60 * 60 * 1000;

// animefillerlist has no search API, just a static directory of every show it covers --
// fetch it once (long TTL, it rarely changes) and fuzzy-match against it, same pattern as
// searchAnimegoCandidates()/stringSimilarity used for the RU anime video source.
async function getAnimeFillerListDirectory() {
    if (animeFillerListDirectoryCache && (Date.now() - animeFillerListDirectoryCache.fetchedAt) < ANIMEFILLERLIST_DIRECTORY_TTL_MS) {
        return animeFillerListDirectoryCache.entries;
    }
    const res = await axios.get('https://www.animefillerlist.com/shows', {
        headers: { 'User-Agent': ANIMEFILLERLIST_UA },
        timeout: 20000
    });
    const $ = cheerio.load(res.data);
    const entries = [];
    $('a[href^="/shows/"]').each((i, el) => {
        const $el = $(el);
        const slug = ($el.attr('href') || '').replace(/^\/shows\//, '');
        const title = $el.text().trim();
        if (!slug || !title) return;
        entries.push({ slug, title });
    });
    animeFillerListDirectoryCache = { entries, fetchedAt: Date.now() };
    return entries;
}

async function resolveAnimeFillerListSlug(rawTitle) {
    const entries = await getAnimeFillerListDirectory();
    const query = rawTitle.toLowerCase();
    let best = null, bestScore = 0;
    for (const e of entries) {
        const score = stringSimilarity.compareTwoStrings(query, e.title.toLowerCase());
        if (score > bestScore) { bestScore = score; best = e; }
    }
    if (!best || bestScore < 0.5) {
        throw new Error(`No animefillerlist match for "${rawTitle}" (closest: ${best?.title || 'none'}, ${Math.round(bestScore * 100)}%)`);
    }
    return best.slug;
}

async function fetchAnimeFillerListEpisodes(slug) {
    const res = await axios.get(`https://www.animefillerlist.com/shows/${slug}`, {
        headers: { 'User-Agent': ANIMEFILLERLIST_UA },
        timeout: 20000
    });
    const $ = cheerio.load(res.data);
    const episodes = [];
    // Table rows are [#, Title, Type, Airdate] - Type is the literal string we need
    // ("Manga Canon" / "Filler" / "Mixed Canon/Filler" / "Anime Canon").
    $('table.EpisodeList tr').each((i, el) => {
        const cells = $(el).find('td');
        if (cells.length < 3) return;
        const epNum = parseInt($(cells[0]).text().trim(), 10);
        const type = $(cells[2]).text().trim();
        if (!epNum || !type) return;
        episodes.push({ episodeNumber: epNum, type });
    });
    return episodes;
}

function fillerCacheKey(rawTitle) {
    return String(rawTitle).toLowerCase().trim();
}

function getCachedFillerEpisodes(cacheKey) {
    return new Promise((resolve) => {
        animeCacheDb.all(
            `SELECT episode_number, type, cached_at FROM anime_episode_filler WHERE cache_key = ?`,
            [cacheKey],
            (err, rows) => resolve(err ? [] : (rows || []))
        );
    });
}

function upsertFillerEpisodes(cacheKey, episodes) {
    const now = Math.floor(Date.now() / 1000);
    return Promise.all(episodes.map(ep => new Promise((resolve) => {
        animeCacheDb.run(
            `INSERT INTO anime_episode_filler (cache_key, episode_number, type, cached_at)
             VALUES (?, ?, ?, ?)
             ON CONFLICT(cache_key, episode_number) DO UPDATE SET type = excluded.type, cached_at = excluded.cached_at`,
            [cacheKey, ep.episodeNumber, ep.type, now],
            () => resolve()
        );
    })));
}

const FILLER_STATUS_TTL_SECONDS = 6 * 60 * 60; // 6h - only matters for "finished" shows below

// `isOngoing` (from TMDB's own status field, passed by the frontend) decides the refresh
// policy: a finished show's filler list never changes once fully aired, so a plain
// TTL-based cache is fine. An ONGOING show gets a new episode roughly weekly, so this
// always tries a live fetch first regardless of cache age - and only falls back to
// whatever's cached if that live attempt fails (animefillerlist down/rate-limited/no
// match), instead of silently serving a stale list missing the newest episodes.
async function getAnimeFillerStatus(rawTitle, isOngoing) {
    const cacheKey = fillerCacheKey(rawTitle);
    const cached = await getCachedFillerEpisodes(cacheKey);
    const cacheFresh = cached.length > 0 &&
        (Math.floor(Date.now() / 1000) - Math.max(...cached.map(r => r.cached_at))) < FILLER_STATUS_TTL_SECONDS;

    if (!isOngoing && cacheFresh) {
        return { episodes: cached, stale: false };
    }

    try {
        const slug = await resolveAnimeFillerListSlug(rawTitle);
        const fresh = await fetchAnimeFillerListEpisodes(slug);
        if (fresh.length === 0) throw new Error('animefillerlist returned no episodes');
        await upsertFillerEpisodes(cacheKey, fresh);
        return { episodes: fresh.map(e => ({ episode_number: e.episodeNumber, type: e.type })), stale: false };
    } catch (err) {
        if (cached.length > 0) {
            logTempDebug('[FillerStatus] Live fetch failed, serving cached', { rawTitle, error: err.message });
            return { episodes: cached, stale: true };
        }
        throw err;
    }
}

app.get('/api/anime-filler-status', async (req, res) => {
    const rawTitle = req.query.title || '';
    const isOngoing = req.query.ongoing === 'true';
    if (!rawTitle) return res.status(400).json({ error: 'title is required' });

    try {
        const { episodes, stale } = await getAnimeFillerStatus(rawTitle, isOngoing);
        const map = {};
        episodes.forEach(e => { map[e.episode_number] = e.type; });
        res.json({ status: 'ready', episodes: map, stale });
    } catch (err) {
        res.json({ status: 'unavailable', episodes: {}, error: err.message });
    }
});

// Shared by the route below AND findMegaplayDubTotalAcrossSeasons (the badge system's MegaPlay
// dub-backfill) - both need the exact same "every real season/cour and its own MAL id" answer,
// and this is also where that answer is cached. findMegaplayDubTotalAcrossSeasons used to run
// its own, more limited resolveAnimeIds(tmdbId, season)-per-TMDB-season loop instead of this,
// which can only ever find a season's COMBINED mal id, never a hidden MAL-only cour split like
// Tower of God's Workshop Battle - confirmed live: the dub-backfill silently missed it the same
// way playback used to before this whole system existed. Routing both callers through this one
// function means they can never drift apart again, and the badge system gets this resolution's
// cache for free instead of re-doing the AniList/MAL work from scratch.
//
// Returns { groups, cached, stale, source, partial } on success, or { groups: [], notFound: true,
// notFoundReason } when nothing could be resolved at all. Throws only when there's truly no
// fallback left (no disk cache either) - the route below is what turns that into a 500.
async function resolveAnimeSeasonGroups(tmdbId) {
    // Fetched once, up front - used both to decide whether an existing cache row is stale (the
    // tmdb_season_count early-bust check) and, later, to record a fresh is_finished/season-count
    // alongside a newly-computed result. Cheap and safe to always fetch - TMDB is our own
    // trusted first-party dependency already hit everywhere else in this file, not a scrape.
    let tmdbStatus = { numberOfSeasons: undefined, isFinished: false };
    try {
        tmdbStatus = await fetchTmdbShowStatus(tmdbId);
    } catch (err) {
        console.warn(`[anime-season-groups] TMDB status fetch failed for tmdb ${tmdbId}:`, err.message);
    }

    let diskCache = null;
    try {
        diskCache = await animeSeasonGroupsCacheGet(tmdbId, tmdbStatus.numberOfSeasons);
        if (diskCache && !diskCache.stale) {
            return { groups: diskCache.groups, cached: true };
        }
    } catch (err) {
        console.error('[anime-season-groups] disk cache read failed:', err.message);
    }

    try {
        const cacheHit = _animeSeasonGroupsCache.get(String(tmdbId));
        if (cacheHit) {
            const ttl = cacheHit.isFinished ? ANIME_SEASON_GROUPS_FINISHED_TTL : ANIME_SEASON_GROUPS_ONGOING_TTL;
            const seasonCountBust = Number.isFinite(tmdbStatus.numberOfSeasons) && Number.isFinite(cacheHit.tmdbSeasonCount) &&
                tmdbStatus.numberOfSeasons > cacheHit.tmdbSeasonCount;
            if (!seasonCountBust && (Date.now() - cacheHit.cachedAt <= ttl)) {
                return { groups: cacheHit.groups, cached: true };
            }
        }

        const ids = await resolveAnimeIds(tmdbId, 1);
        if (!ids || (!ids.malId && !ids.anilistId)) {
            if (diskCache) return { groups: diskCache.groups, cached: true, stale: true };
            return { groups: [], notFound: true, notFoundReason: 'No MAL/AniList mapping for this TMDB anime' };
        }

        let metaList = [];
        let failedLookups = 0;
        let source = null;
        // Set by buildSeasonGroupsFromAniList when it sees a SEQUEL relation sitting at
        // NOT_YET_RELEASED/RELEASING - a "FINISHED" show never flips its OWN status back, the
        // sequel is always a separate node, so this is the only way to catch an announced-but-
        // not-yet-TMDB-listed continuation immediately instead of waiting on tmdb_season_count.
        let hasUpcomingSequel = false;
        // The franchise's own {english, romaji, native} title triple, used only to let
        // runFinishedShowScheduleAudit fuzzy-match this cached row against AniList's daily
        // airing schedule once it's marked finished - a real sequel airs under its OWN
        // AniList id, so id-matching can't catch it, only title-matching can.
        let baseTitle = null;

        // Primary: AniList relations graph.
        if (ids.anilistId) {
            try {
                const r = await buildSeasonGroupsFromAniList(ids.anilistId);
                metaList = r.metaList;
                failedLookups = r.failedLookups;
                hasUpcomingSequel = r.hasUpcomingSequel;
                baseTitle = r.baseTitle;
                source = 'anilist';
            } catch (err) {
                console.warn(`[anime-season-groups] anilist primary failed for tmdb ${tmdbId}:`, err.message);
            }
        }

        // Fallback: MAL's own relations graph (scraped directly), only if AniList found nothing
        // beyond the base season. Was Jikan-backed (buildSeasonGroupsFromJikan, still defined
        // above, kept intact not deleted) - switched to buildSeasonGroupsFromMalRelations since
        // Jikan is both unreliable (504/429 on individual lookups all session) and headed for
        // its own sunset within about a month at the time of this change. Scraping MAL directly
        // removes that dependency entirely for this fallback layer.
        if (metaList.length <= 1 && ids.malId) {
            try {
                const r = await buildSeasonGroupsFromMalRelations(ids.malId);
                // const r = await buildSeasonGroupsFromJikan(ids.malId); // old Jikan path, see above
                if (r.metaList.length > metaList.length) {
                    metaList = r.metaList;
                    failedLookups = r.failedLookups;
                    source = 'mal-relations';
                }
            } catch (err) {
                console.warn(`[anime-season-groups] mal-relations fallback failed for tmdb ${tmdbId}:`, err.message);
            }
        }

        if (metaList.length === 0) {
            // Neither AniList nor Jikan resolved anything; the frontend's own TMDB
            // title-search fallback (buildTmdbRelatedSeasonGroups) is the last tier.
            if (diskCache) return { groups: diskCache.groups, cached: true, stale: true };
            return { groups: [], notFound: true, notFoundReason: 'Could not resolve season groups from AniList or MAL' };
        }

        // Last-resort layer: a cour split that exists ONLY on MAL's side, with no relations
        // edge on either AniList's or MAL's own graph (confirmed live: Tower of God's
        // "Workshop Battle" - see findMalOnlyCourSiblings above for the full story). Anchored
        // on the FIRST/earliest known entry's own romaji title, not the latest - a later
        // season's own title usually carries its own qualifier suffix (e.g. "... 2nd Season"),
        // which pushes isAnikotoVariantDivergence's short-remainder check past its 3-token cap
        // and silently finds nothing (confirmed live: anchoring on Season 2's own title matched
        // zero candidates; anchoring on Season 1's clean base title correctly found Workshop
        // Battle). The base/earliest entry's title is the closest thing to the franchise's
        // "clean" name every real sibling should share a prefix with.
        try {
            const anchor = metaList[0];
            const malSiblings = await findMalOnlyCourSiblings(
                anchor.title,
                anchor.romajiTitle || anchor.title,
                metaList.map(m => m.malId)
            );
            if (malSiblings.length) {
                // AniList's own `episodes` count for an entry can be the COMBINED total across
                // a split it doesn't track separately (confirmed live: AniList's "Tower of God
                // Season 2" entry, mal id 52635, reports episodes:26 - the real total across
                // BOTH cours together - while MAL's OWN page for that exact same id says
                // Episodes: 13, matching only "Return of the Prince"; "Workshop Battle"'s other
                // 13 episodes live under the separate mal id just discovered above). Leaving the
                // existing entries' counts at AniList's inflated number would make the site keep
                // trying to map local episodes 1-26 onto an id that only has 13 - the exact same
                // 404 this whole layer exists to fix, just moved rather than solved. Re-checking
                // every existing entry's OWN MAL page and correcting DOWNWARD only (never up -
                // AniList's number is still trusted when it's the smaller/more conservative one)
                // is what actually closes that gap.
                for (const existing of metaList) {
                    if (!existing.malId) continue;
                    try {
                        const details = await fetchMalAnimeDetails(existing.malId);
                        if (Number.isFinite(details.episodes) && details.episodes > 0 && details.episodes < existing.episodesCount) {
                            logAnikotoDebug(`[anime-season-groups] correcting mal ${existing.malId} episodesCount ${existing.episodesCount} -> ${details.episodes} (AniList total appears combined across a split MAL doesn't)`);
                            existing.episodesCount = details.episodes;
                            // metaListToGroups computes each group's real episode count as
                            // Math.max(episodesCount, streamingEpisodes.length) - correcting
                            // episodesCount alone is silently overridden if AniList's own
                            // streamingEpisodes listing still has the old, larger (combined)
                            // count sitting in it (confirmed live: this exact gap is what made
                            // Workshop Battle's thumbnails come up blank - "Return of the Prince"
                            // kept consuming 26 slots from the concatenated TMDB array via its
                            // uncorrected streamingEpisodes length, leaving nothing for Workshop
                            // Battle's own slice). Truncating it to match keeps both signals
                            // consistent with the real, corrected count.
                            if (Array.isArray(existing.streamingEpisodes) && existing.streamingEpisodes.length > details.episodes) {
                                existing.streamingEpisodes = existing.streamingEpisodes.slice(0, details.episodes);
                            }
                        }
                    } catch (err) {
                        logAnikotoDebug(`[anime-season-groups] episode-count re-check failed for mal ${existing.malId}`, { error: err.message || String(err) });
                    }
                }
            }
            for (const s of malSiblings) {
                logAnikotoDebug(`[anime-season-groups] MAL-only sibling found for tmdb ${tmdbId}: "${s.title}" (mal ${s.malId})`);
                metaList.push({
                    title: s.title,
                    // The romaji/native title (findMalOnlyCourSiblings' titleNative) - kept
                    // separately for KAA specifically, whose own catalog is titled in romaji,
                    // not English. `title` above is now English (see findMalOnlyCourSiblings),
                    // matching every other entry's convention and what Neko/anikoto need.
                    romajiTitle: s.titleNative || s.title,
                    episodesCount: s.episodesCount,
                    airDate: s.airDate,
                    streamingEpisodes: [],
                    malId: s.malId
                });
            }
            if (malSiblings.length) {
                source = source ? `${source}+mal-search` : 'mal-search';
                // Universal safety net, applied to EVERY entry (not just the ones the targeted
                // correction above touched) - AniList's own streamingEpisodes listing can be
                // duplicated/inflated onto a sibling it doesn't actually belong to (the same
                // quirk metaListToGroups already documents further down: "AniList sometimes
                // duplicates one season's streamingEpisodes listing onto a sibling season's
                // entry"). Confirmed live: Tower of God's own SEASON 1 entry (mal 40221) came
                // back with episodesCount:26 in the final output despite its own episodesCount
                // field always having been the correct 13 - its streamingEpisodes array itself
                // had ballooned past 13 entries, and metaListToGroups' `total = Math.max(...,
                // streaming.length)` let that alone widen the count. Only reachable once a
                // MAL-only split is confirmed to exist for this title at all (malSiblings.length
                // > 0) - a title with no such split has no reason to distrust its own data here.
                for (const existing of metaList) {
                    if (Array.isArray(existing.streamingEpisodes) && Number.isFinite(existing.episodesCount) &&
                        existing.streamingEpisodes.length > existing.episodesCount) {
                        logAnikotoDebug(`[anime-season-groups] truncating streamingEpisodes for mal ${existing.malId}: ${existing.streamingEpisodes.length} -> ${existing.episodesCount}`);
                        existing.streamingEpisodes = existing.streamingEpisodes.slice(0, existing.episodesCount);
                    }
                }
            }
        } catch (err) {
            logAnikotoDebug(`[anime-season-groups] MAL-only sibling discovery failed for tmdb ${tmdbId}`, { error: err.message || String(err) });
        }

        let tmdbEpisodes = [];
        try {
            tmdbEpisodes = await fetchTmdbRealSeasonEpisodes(tmdbId);
        } catch (err) {
            console.warn(`[anime-season-groups] TMDB real-episode fetch failed for tmdb ${tmdbId}, falling back to AniList streaming data:`, err.message);
        }

        const groups = metaListToGroups(metaList, tmdbEpisodes);

        // A partial walk can hide seasons we already have on disk from a healthier run,
        // so only overwrite the cache when this result is at least as complete.
        if (failedLookups > 0 && diskCache && diskCache.groups.length > groups.length) {
            console.warn(`[anime-season-groups] tmdb ${tmdbId}: partial walk (${groups.length} group(s) via ${source}, ${failedLookups} failed); serving cached ${diskCache.groups.length}`);
            return { groups: diskCache.groups, cached: true, stale: true };
        }

        // TMDB's own status alone isn't enough - it can say "Ended" for weeks/months after
        // AniList already knows a real sequel is announced or airing (see hasUpcomingSequel's
        // comment above). Only trust the long "finished" TTL when BOTH agree nothing more is
        // coming.
        const trulyFinished = tmdbStatus.isFinished && !hasUpcomingSequel;
        if (hasUpcomingSequel && tmdbStatus.isFinished) {
            logAnikotoDebug(`[anime-season-groups] tmdb ${tmdbId}: TMDB says finished but AniList shows an upcoming/airing sequel - caching as ongoing, not finished`);
        }

        _animeSeasonGroupsCache.set(String(tmdbId), {
            groups, cachedAt: Date.now(), isFinished: trulyFinished, tmdbSeasonCount: tmdbStatus.numberOfSeasons
        });
        try {
            await animeSeasonGroupsCacheSet(tmdbId, ids.malId || null, groups, trulyFinished, tmdbStatus.numberOfSeasons, baseTitle);
        } catch (err) {
            console.error('[anime-season-groups] disk cache write failed:', err.message);
        }
        return { groups, cached: false, source, partial: failedLookups > 0 };
    } catch (err) {
        console.error('[anime-season-groups]', err.message);
        // Upstream is down but we resolved this title before: stale beats nothing, since the
        // caller's only other option is fuzzy TMDB title matching.
        if (diskCache) {
            console.warn(`[anime-season-groups] tmdb ${tmdbId}: serving stale cache after failure`);
            return { groups: diskCache.groups, cached: true, stale: true };
        }
        throw err;
    }
}

// --- Finished-show schedule audit -------------------------------------------------------
// A "finished" row (anime_season_groups_cache.is_finished=1, and native_episode_counts'
// equivalent) is now essentially permanent (ANIME_SEASON_GROUPS_FINISHED_TTL = Infinity above) -
// blind periodic re-checks per title were pure waste for the overwhelming majority of finished
// shows that never get a sequel. The only real way that state can go stale is a genuinely new
// sequel being announced/airing, and that's only ever discoverable by re-walking AniList's
// relations graph per title - the exact expensive N-calls-per-title cost an infinite TTL exists
// to avoid paying. This inverts the check: instead of N per-title live AniList audits, do ONE
// shared daily fetch of "what's airing/scheduled across all of AniList soon" (the same
// anime_schedule data the calendar feature already caches) and fuzzy-match every cached
// "finished" title's own title triple against it. A hit means something is airing/scheduled
// under a title that looks like this "finished" franchise - a real sequel airs under its OWN,
// different AniList/MAL id, so this can only ever be a title match, never an id match.
// Only this month and next month, not a flat day count - anything further out is the same
// unreliable/still-being-revealed AniList data isWithinReliableScheduleWindow above exists to
// stop caching forever. A distant month being sparse today would otherwise read as "nothing's
// airing" and never get a chance to catch a real match once that month actually fills in.
const FINISHED_SHOW_AUDIT_TITLE_MATCH_THRESHOLD = 0.8;

function finishedAuditTitleVariants(...titles) {
    return titles.filter(Boolean).map(t => String(t).toLowerCase().trim()).filter(Boolean);
}

function finishedAuditTitlesMatch(rowVariants, scheduleVariants, threshold) {
    for (const r of rowVariants) {
        for (const s of scheduleVariants) {
            if (stringSimilarity.compareTwoStrings(r, s) >= threshold) return true;
        }
    }
    return false;
}

async function runFinishedShowScheduleAudit() {
    logHealthStatus('[FinishedShowAudit] Starting daily finished-show schedule audit...');
    try {
        const now = new Date();
        const todayIso = isoDateUTC(now);
        // Last day of NEXT month: day 0 of the month after next rolls back to the last day
        // of the month before it.
        const endIso = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + 2, 0)).toISOString().slice(0, 10);

        const grouped = await fetchAniListRangeScheduleByDate(todayIso, endIso);
        // Persist what this walk just paid for, so the calendar's own endpoints (now
        // cache-forever, see /api/anime-schedule above) don't need to re-fetch these same
        // dates later just because a user happens to browse to them.
        for (const [iso, items] of Object.entries(grouped)) {
            try {
                await animeScheduleUpsert(iso, dayNameFromDate(iso), JSON.stringify({ data: items }));
            } catch (err) {
                logHealthStatus(`[FinishedShowAudit] schedule cache write failed for ${iso}: ${err.message}`);
            }
        }

        // Dedup by idMal across the whole window - the same show airs on many dates.
        const seenMalIds = new Set();
        const scheduleCandidates = [];
        for (const items of Object.values(grouped)) {
            for (const item of items) {
                if (item.idMal) {
                    if (seenMalIds.has(item.idMal)) continue;
                    seenMalIds.add(item.idMal);
                }
                const variants = finishedAuditTitleVariants(item.title, item.title_english, item.title_native);
                if (variants.length) scheduleCandidates.push(variants);
            }
        }

        // Beyond next month, don't pay for a live AniList fetch here at all - the calendar
        // feature (/api/anime-schedule-range) already caches whatever far-future dates a user
        // has actually browsed to, refreshing each one weekly (ANIME_SCHEDULE_FAR_FUTURE_REFRESH_MS)
        // on its own. Reusing those rows here is free (no extra request) and widens this audit's
        // catch window past the reliable 2-month one above for whatever's already sitting in the
        // table - a sequel announced 6 months out that someone has browsed to on the calendar
        // gets caught by this audit immediately instead of waiting for the 180-day finished TTL
        // to expire on its own. Rows nobody's browsed to yet just aren't in the table - that's
        // fine, they still get caught later once EITHER someone browses there OR the date itself
        // rolls inside the reliable 2-month window and the live fetch above picks it up.
        try {
            const farFutureRows = await new Promise((resolve, reject) => {
                animeCacheDb.all(
                    `SELECT json FROM anime_schedule WHERE date > ?`,
                    [endIso],
                    (err, rows) => err ? reject(err) : resolve(rows || [])
                );
            });
            for (const row of farFutureRows) {
                let parsed;
                try { parsed = JSON.parse(row.json); } catch (e) { continue; }
                const items = parsed?.data;
                if (!Array.isArray(items)) continue;
                for (const item of items) {
                    if (item.idMal) {
                        if (seenMalIds.has(item.idMal)) continue;
                        seenMalIds.add(item.idMal);
                    }
                    const variants = finishedAuditTitleVariants(item.title, item.title_english, item.title_native);
                    if (variants.length) scheduleCandidates.push(variants);
                }
            }
            logHealthStatus(`[FinishedShowAudit] widened with ${farFutureRows.length} far-future anime_schedule row(s) already cached from calendar browsing`);
        } catch (err) {
            logHealthStatus(`[FinishedShowAudit] far-future anime_schedule scan failed: ${err.message}`);
        }

        if (!scheduleCandidates.length) {
            logHealthStatus('[FinishedShowAudit] No schedule candidates in window; nothing to audit.');
            return;
        }

        let seasonGroupsBusted = 0;
        let nativeBusted = 0;

        const seasonGroupRows = await new Promise((resolve, reject) => {
            animeCacheDb.all(
                `SELECT tmdb_id, title_en, title_romaji, title_native FROM anime_season_groups_cache WHERE is_finished = 1`,
                [],
                (err, rows) => err ? reject(err) : resolve(rows || [])
            );
        });
        for (const row of seasonGroupRows) {
            const rowVariants = finishedAuditTitleVariants(row.title_en, row.title_romaji, row.title_native);
            if (!rowVariants.length) continue;
            const matched = scheduleCandidates.some(sv => finishedAuditTitlesMatch(rowVariants, sv, FINISHED_SHOW_AUDIT_TITLE_MATCH_THRESHOLD));
            if (!matched) continue;
            await new Promise((resolve, reject) => {
                animeCacheDb.run(
                    `UPDATE anime_season_groups_cache SET is_finished = 0 WHERE tmdb_id = ?`,
                    [row.tmdb_id],
                    (err) => err ? reject(err) : resolve()
                );
            });
            _animeSeasonGroupsCache.delete(String(row.tmdb_id));
            seasonGroupsBusted++;
            logHealthStatus(`[FinishedShowAudit] anime_season_groups_cache tmdb ${row.tmdb_id} ("${row.title_en || row.title_romaji || row.title_native}") matched the airing schedule - busted back to ongoing TTL`);
        }

        const nativeRows = await new Promise((resolve, reject) => {
            animeCacheDb.all(
                `SELECT normalized_title FROM native_episode_counts WHERE is_finished = 1`,
                [],
                (err, rows) => err ? reject(err) : resolve(rows || [])
            );
        });
        for (const row of nativeRows) {
            const rowVariants = finishedAuditTitleVariants(row.normalized_title);
            if (!rowVariants.length) continue;
            const matched = scheduleCandidates.some(sv => finishedAuditTitlesMatch(rowVariants, sv, FINISHED_SHOW_AUDIT_TITLE_MATCH_THRESHOLD));
            if (!matched) continue;
            await new Promise((resolve, reject) => {
                animeCacheDb.run(
                    `UPDATE native_episode_counts SET is_finished = 0 WHERE normalized_title = ?`,
                    [row.normalized_title],
                    (err) => err ? reject(err) : resolve()
                );
            });
            nativeBusted++;
            logHealthStatus(`[FinishedShowAudit] native_episode_counts "${row.normalized_title}" matched the airing schedule - busted back to ongoing TTL`);
        }

        logHealthStatus(`[FinishedShowAudit] Done. season-groups: ${seasonGroupRows.length} finished row(s) checked, ${seasonGroupsBusted} busted. native: ${nativeRows.length} finished row(s) checked, ${nativeBusted} busted.`);
    } catch (err) {
        logHealthStatus(`[FinishedShowAudit] FAILED: ${err.message}`);
    }
}
const FINISHED_SHOW_AUDIT_INTERVAL_MS = 24 * 60 * 60 * 1000; // once a day, per the user's spec

// --- Season cards row (test feature) -------------------------------------------------------
// Separate from resolveAnimeSeasonGroups above on purpose - that one builds this SAME show's
// own episode list per TMDB season (no cover art, since it's all one TMDB entry). This walks
// AniList's own relations graph instead, the same SEQUEL/PREQUEL BFS shape
// buildSeasonGroupsFromAniList already uses, but keeps each season's own coverImage (which that
// function deliberately doesn't fetch - metaListToGroups never needed it) and resolves each
// season's own tmdbId so a card can link straight to that season's movieInfo.html page.
const ANIME_SEASON_CARDS_QUERY = `
    query ($id: Int) {
        Media(id: $id, type: ANIME) {
            id
            idMal
            format
            status
            title { romaji english native }
            startDate { year month day }
            coverImage { extraLarge }
            relations {
                edges {
                    relationType(version: 2)
                    node {
                        id
                        type
                        format
                        status
                        title { romaji english native }
                        startDate { year month day }
                        coverImage { extraLarge }
                    }
                }
            }
        }
    }
`;

// Same retry-with-backoff shape as aniListGetMediaWithRelations - this function makes several
// rapid sequential AniList calls per show (one per BFS hop, plus getTmdbIdForAniList per season
// found), and AniList genuinely 429s under that pattern. Confirmed live this was the actual
// cause of a real, reported "shows 2 seasons instead of 3" bug: no retry meant a single 429 on
// any hop silently dropped that season for good (the catch below just skipped it), and the
// resulting INCOMPLETE list then got cached as if it were the full, correct answer.
// Retries on 429 (rate limit) AND 403/5xx - AniList has had whole-site outages ("temporarily
// disabled due to severe stability issues", a real 403 seen live) that look nothing like a
// per-request rate limit but are just as transient. Worth a few patient retries before ever
// falling to the Jikan/MAL last resort below, since AniList is the primary source and Jikan's
// own scrape is the weaker of the two.
async function fetchAniListMediaForSeasonCards(anilistId) {
    const maxAttempts = 4;
    let delay = 600;
    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
        try {
            const response = await axios.post(
                'https://graphql.anilist.co',
                { query: ANIME_SEASON_CARDS_QUERY, variables: { id: anilistId } },
                { headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' }, timeout: 15000 }
            );
            if (response.data?.errors) throw new Error(`AniList error: ${JSON.stringify(response.data.errors)}`);
            return response.data?.data?.Media || null;
        } catch (err) {
            const status = err.response?.status;
            const retryable = status === 429 || status === 403 || (status >= 500 && status < 600);
            if (retryable && attempt < maxAttempts) {
                await sleep(delay);
                delay *= 2;
                continue;
            }
            throw err;
        }
    }
    throw new Error('AniList request failed');
}

// Jikan/MAL fallback for when AniList's own BFS above comes back incomplete - same relations-
// walk buildSeasonGroupsFromJikan already does for resolveAnimeSeasonGroups (AniList-then-Jikan
// is an established pattern in this file, not a new one), but this copy also keeps each
// season's own cover image (jikanGet already retries internally, see its own definition).
async function fetchJikanSeasonCardsChain(malId) {
    const visited = new Set();
    const queue = [Number(malId)];
    const found = [];
    while (queue.length && found.length < 8) {
        const id = Number(queue.shift());
        if (!id || visited.has(id)) continue;
        visited.add(id);

        let full;
        try {
            full = await jikanGet(`/anime/${id}/full`);
        } catch (err) {
            continue; // one unreachable MAL entry shouldn't drop the rest of this fallback chain
        }
        const info = full?.data;
        if (!info) continue;

        if (String(info.type || '').toUpperCase() === 'TV') {
            found.push({
                idMal: info.mal_id || id,
                title: info.title_english || info.title || null,
                coverImage: info.images?.jpg?.large_image_url || info.images?.webp?.large_image_url || null,
                airDate: info?.aired?.from ? String(info.aired.from).slice(0, 10) : null,
                status: String(info.status || '').toLowerCase().includes('airing') ? 'RELEASING'
                    : String(info.status || '').toLowerCase().includes('not yet') ? 'NOT_YET_RELEASED' : 'FINISHED'
            });
        }

        const rels = Array.isArray(info.relations) ? info.relations : [];
        rels.forEach(rel => {
            const rType = String(rel?.relation || '').toLowerCase();
            if (rType !== 'sequel' && rType !== 'prequel') return;
            (rel.entry || []).forEach(ent => {
                if (String(ent?.type || '').toLowerCase() !== 'anime') return;
                const relId = Number(ent?.mal_id || 0);
                if (relId > 0 && !visited.has(relId)) queue.push(relId);
            });
        });
    }
    return found;
}

// Persisted in anime_season_cards_cache (see its CREATE TABLE / migration comment above) instead
// of an in-memory Map, so a good result survives a server restart the same way every other
// AniList/Jikan-backed cache in this file already does.
//
// Freshness reuses the EXACT native_episode_counts/anikoto_episode_counts TTL tiers
// (ANIKOTO_FINISHED_CACHE_TTL_MS etc., defined near getAnyCachedNativeRow) rather than inventing
// new constants - "is this franchise still getting updates" is the same question either cache is
// answering, just about a different piece of data. is_finished here is computed the same way
// resolveAnimeSeasonGroups computes hasUpcomingSequel: the latest known season is FINISHED with no
// upcoming sequel in sight -> long TTL; still RELEASING/NOT_YET_RELEASED, or a real SEQUEL relation
// already sitting at one of those statuses -> short "check again soon" TTL.
function animeSeasonCardsCacheGet(tmdbId, currentTmdbSeasonCount) {
    return new Promise((resolve, reject) => {
        animeCacheDb.get(`SELECT * FROM anime_season_cards_cache WHERE tmdb_id = ?`, [tmdbId], (err, row) => {
            if (err) return reject(err);
            if (!row) return resolve(null);
            let seasons;
            try {
                seasons = JSON.parse(row.seasons_json);
            } catch {
                return resolve(null);
            }
            const seasonCountBust = row.is_finished === 1 && Number.isFinite(currentTmdbSeasonCount) &&
                Number.isFinite(row.tmdb_season_count) && currentTmdbSeasonCount > row.tmdb_season_count;
            const isNegative = !seasons.length;
            const finishedTtl = Number.isFinite(row.tmdb_season_count)
                ? ANIKOTO_FINISHED_CACHE_TTL_MS
                : ANIKOTO_FINISHED_NO_SIGNAL_CACHE_TTL_MS;
            const ttl = row.is_finished === 1 ? finishedTtl
                : (isNegative ? ANIKOTO_NEGATIVE_CACHE_TTL_MS : ANIKOTO_EPISODE_COUNTS_CACHE_TTL_MS);
            const age = Date.now() - Number(row.cached_at || 0);
            resolve({ seasons, malId: row.mal_id, incomplete: false, stale: seasonCountBust || age > ttl });
        });
    });
}

function animeSeasonCardsCacheSet(tmdbId, malId, seasons, isFinished, tmdbSeasonCount, title) {
    return new Promise((resolve, reject) => {
        const now = Date.now();
        animeCacheDb.run(
            `INSERT INTO anime_season_cards_cache (tmdb_id, mal_id, seasons_json, season_count, cached_at, is_finished, tmdb_season_count, title)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?)
             ON CONFLICT(tmdb_id) DO UPDATE SET
                 mal_id = excluded.mal_id,
                 seasons_json = excluded.seasons_json,
                 season_count = excluded.season_count,
                 cached_at = excluded.cached_at,
                 is_finished = excluded.is_finished,
                 tmdb_season_count = excluded.tmdb_season_count,
                 title = COALESCE(excluded.title, anime_season_cards_cache.title)`,
            [tmdbId, malId || null, JSON.stringify(seasons), seasons.length, now,
                isFinished ? 1 : 0, Number.isFinite(tmdbSeasonCount) ? tmdbSeasonCount : null, title || null],
            function (err) {
                if (err) return reject(err);
                resolve(this.changes || 0);
            }
        );
    });
}

async function resolveAnimeSeasonCards(tmdbId) {
    // Fetched once, up front - used both to decide whether an existing cache row is stale (the
    // tmdb_season_count early-bust check) and, later, to record a fresh is_finished/season-count
    // alongside a newly-computed result. Same pattern as resolveAnimeSeasonGroups.
    let tmdbSeasonCount;
    try {
        const tmdbStatus = await fetchTmdbShowStatus(tmdbId);
        tmdbSeasonCount = tmdbStatus.numberOfSeasons;
    } catch (err) {
        console.warn(`[anime-season-cards] TMDB status fetch failed for tmdb ${tmdbId}:`, err.message);
    }

    let diskCache = null;
    try {
        diskCache = await animeSeasonCardsCacheGet(tmdbId, tmdbSeasonCount);
        if (diskCache && !diskCache.stale) return diskCache.seasons;
    } catch (err) {
        console.error('[anime-season-cards] disk cache read failed:', err.message);
    }

    // anime_tmdb_mapping is keyed by tmdb_id already (see its own CREATE TABLE) - a direct
    // reverse lookup, no title search needed for the common case where this show has already
    // been resolved once via any of the other anime features that populate this table.
    const mapping = await new Promise((resolve, reject) => {
        animeCacheDb.get(`SELECT anilist_id, mal_id FROM anime_tmdb_mapping WHERE tmdb_id = ?`, [tmdbId],
            (err, row) => err ? reject(err) : resolve(row));
    });
    let anilistId = mapping?.anilist_id || null;
    let mappedMalId = mapping?.mal_id || null;
    if (!anilistId) {
        // Fallback: anime_cache's own tmdb_id column (PK is anilist_id there) - a title might
        // have been cached via the homepage rows/library browsing without ever going through
        // anime_tmdb_mapping specifically.
        const cacheRow = await new Promise((resolve, reject) => {
            animeCacheDb.get(`SELECT anilist_id, mal_id FROM anime_cache WHERE tmdb_id = ?`, [tmdbId],
                (err, row) => err ? reject(err) : resolve(row));
        });
        anilistId = cacheRow?.anilist_id || null;
        mappedMalId = mappedMalId || cacheRow?.mal_id || null;
    }
    if (!mappedMalId && !anilistId) {
        // No mapping at all - this table is anime-only, and having neither a MAL nor an AniList
        // id here means anime_tmdb_mapping/anime_cache (the app's own "is this anime" signal
        // elsewhere) never recognized this tmdb_id as anime. renderSeasonCardsRow calls this
        // endpoint unconditionally for every TV show, anime or not (see its own comment in
        // moviePlayer.js), so deliberately do NOT write a row here - a plain TV show like Game
        // of Thrones or Cold has no business occupying a row in an anime-specific cache table,
        // even a negative one. The cost is repeating this cheap local mapping lookup on every
        // non-anime TV page load instead of skipping it via cache; worth it to keep the table
        // anime-only.
        return [];
    }

    const found = []; // { anilistId, idMal, title, coverImage, airDate, status }
    let hadFailure = false;
    let hasUpcomingSequel = false;
    const isLookingComplete = () => !(Number.isFinite(tmdbSeasonCount) && tmdbSeasonCount > 0 && found.length < tmdbSeasonCount);
    const mergeResults = (chainFound, withAnilistIds) => {
        const existingMalIds = new Set(found.map(f => f.idMal).filter(Boolean));
        const existingAnilistIds = new Set(found.map(f => f.anilistId).filter(Boolean));
        let addedAny = false;
        for (const cf of chainFound) {
            const cfAnilistId = withAnilistIds ? (cf.anilistId || null) : null;
            if ((cf.idMal && existingMalIds.has(cf.idMal)) || (cfAnilistId && existingAnilistIds.has(cfAnilistId))) continue;
            found.push({ anilistId: cfAnilistId, idMal: cf.idMal || null, title: cf.title, coverImage: cf.coverImage, airDate: cf.airDate, status: cf.status });
            if (cf.idMal) existingMalIds.add(cf.idMal);
            if (cfAnilistId) existingAnilistIds.add(cfAnilistId);
            addedAny = true;
            if (cf.status === 'RELEASING' || cf.status === 'NOT_YET_RELEASED') hasUpcomingSequel = true;
        }
        return addedAny;
    };

    // MAL is primary now, AniList the fallback - direct MAL scraping has been the more reliable
    // of the two live this session (confirmed: it independently found all 7 real Attack on Titan
    // entries, one more than AniList itself returned; and separately closed a gap AniList left on
    // Arifureta). AniList also wraps a GraphQL service that's had whole-site 403 outages
    // ("temporarily disabled due to severe stability issues") on top of its own incompleteness
    // issues, so it's demoted below MAL rather than removed.
    const startMalId = mappedMalId || null;
    if (startMalId) {
        try {
            const malFound = await buildSeasonCardsFromMalRelations(startMalId, tmdbSeasonCount);
            mergeResults(malFound, false);
        } catch (err) {
            hadFailure = true;
        }
    }

    // Fallback to AniList's own relations BFS - only reached when MAL had nothing to start from,
    // threw outright, or came back demonstrably short per the TMDB count check. Same BFS shape as
    // buildSeasonGroupsFromAniList: only TV entries are real "seasons", but still walk through
    // movies/OVAs in case a real season is only reachable through one.
    if (anilistId && (!startMalId || hadFailure || !isLookingComplete())) {
        const aniListFound = [];
        let aniListHadFailure = false;
        const visited = new Set();
        const queue = [anilistId];
        while (queue.length && found.length + aniListFound.length < 8) {
            const id = Number(queue.shift());
            if (!id || visited.has(id)) continue;
            visited.add(id);

            let media;
            try {
                media = await fetchAniListMediaForSeasonCards(id);
            } catch (err) {
                // One unreachable node (even after fetchAniListMediaForSeasonCards' own retries)
                // shouldn't drop the rest of the chain - but it DOES mean this result might be
                // missing a real season reachable only through this node.
                aniListHadFailure = true;
                continue;
            }
            if (!media) continue;

            const isTvFormat = ['TV', 'TV_SHORT'].includes(String(media.format || '').toUpperCase());
            if (isTvFormat) {
                aniListFound.push({
                    anilistId: media.id,
                    idMal: media.idMal || null,
                    title: media.title?.english || media.title?.romaji || media.title?.native || null,
                    coverImage: media.coverImage?.extraLarge || null,
                    airDate: aniListDateToIso(media.startDate),
                    status: String(media.status || '').toUpperCase()
                });
            }

            const edges = Array.isArray(media.relations?.edges) ? media.relations.edges : [];
            for (const edge of edges) {
                const rType = String(edge?.relationType || '').toUpperCase();
                if (rType !== 'SEQUEL' && rType !== 'PREQUEL') continue;
                const node = edge?.node;
                if (!node || String(node.type || '').toUpperCase() !== 'ANIME') continue;
                if (rType === 'SEQUEL') {
                    const nodeStatus = String(node.status || '').toUpperCase();
                    if (nodeStatus === 'NOT_YET_RELEASED' || nodeStatus === 'RELEASING') hasUpcomingSequel = true;
                }
                if (!['TV', 'TV_SHORT'].includes(String(node.format || '').toUpperCase())) continue;
                const relId = Number(node.id || 0);
                if (relId > 0 && !visited.has(relId)) queue.push(relId);
            }
        }
        const closedGap = mergeResults(aniListFound, true);
        // AniList closing the gap (or at least adding something MAL didn't have) clears
        // hadFailure - MAL's own failure/incompleteness doesn't matter anymore if the combined
        // result is now actually complete, re-checked against tmdbSeasonCount below.
        if (closedGap && !aniListHadFailure) hadFailure = false;
        else if (!closedGap) hadFailure = hadFailure || aniListHadFailure;
    }

    // Jikan is the last-resort-of-the-last-resort - same MAL data as the direct scrape above,
    // wrapped in a service that's both flakier (confirmed live: sustained 504s on individual
    // titles across all its own internal retries) and headed for its own sunset. Only reached if
    // MAL direct AND AniList both still leave this short. Its result is good enough to answer
    // THIS request but never trusted enough to persist - usedJikan below skips the disk-cache
    // write entirely, so the next request starts fresh from MAL/AniList instead of getting stuck
    // serving a Jikan-derived result until some TTL expires.
    let usedJikan = false;
    if (startMalId && !isLookingComplete()) {
        try {
            const jikanFound = await fetchJikanSeasonCardsChain(startMalId);
            if (mergeResults(jikanFound, false)) {
                hadFailure = false;
                usedJikan = true;
            }
        } catch (err) {
            // Jikan also failed - hadFailure/incompleteness stands, short TTL below still applies.
        }
    }

    found.sort((a, b) => {
        const ta = Date.parse(a.airDate || ''); const tb = Date.parse(b.airDate || '');
        return (Number.isNaN(ta) ? Infinity : ta) - (Number.isNaN(tb) ? Infinity : tb);
    });

    const seasons = [];
    for (let i = 0; i < found.length; i++) {
        const f = found[i];
        let seasonTmdbId = null;
        try {
            seasonTmdbId = await getTmdbIdForAniList(f.anilistId, f.title, f.idMal);
        } catch (err) {
            // No TMDB match - card still renders, just isn't clickable.
        }
        // The anime industry splits franchises up too inconsistently for a plain array
        // index to mean anything (confirmed live: a franchise with entries titled "IV",
        // "IV Part 2", and "V" showed as index-based "Season 6"/"Season 7"/"Season 8" -
        // technically true by position, but meaningless against the show's OWN numbering,
        // which the card's own subtitle already displays right next to it). Parse the
        // real season number straight out of each entry's title instead (same numeral/
        // ordinal detection KAA's candidate sorting already uses) so the label agrees
        // with what the subtitle says. Two split-cour entries sharing one real season
        // number (e.g. "IV" and "IV Part 2" both parsing to 4) is the correct, honest
        // result, not a bug - they ARE the same season.
        seasons.push({
            seasonNumber: parseAnimeTitle(f.title).season,
            title: f.title,
            coverImage: f.coverImage,
            anilistId: f.anilistId,
            tmdbId: seasonTmdbId
        });
    }

    const latestStatus = found.length ? found[found.length - 1].status : null;
    // Same is_finished meaning getAnyCachedNativeRow/animeSeasonGroupsCacheGet use: no evidence
    // of more content coming -> finished (long TTL, tiered further by whether a real
    // tmdb_season_count signal is on record); still airing/announced -> not finished (short TTL).
    const isFinished = !(hasUpcomingSequel || latestStatus === 'RELEASING' || latestStatus === 'NOT_YET_RELEASED');
    const malIdForWrite = found.find(f => f.idMal)?.idMal || mappedMalId || null;
    // Purely a DB-browser convenience column - the earliest-airing found season's own title
    // stands in for "the franchise's title" well enough for that purpose.
    const titleForWrite = found[0]?.title || null;

    // Re-checked AFTER the Jikan attempt (not the pre-fallback aniListLooksIncomplete) - Jikan may
    // have closed the gap entirely, in which case this is a real, trustworthy result and deserves
    // the normal TTL below even though AniList alone needed help getting there.
    const stillIncomplete = hadFailure || (Number.isFinite(tmdbSeasonCount) && tmdbSeasonCount > 0 && found.length < tmdbSeasonCount);

    // Jikan is never persisted, trustworthy result or not - it's an explicit trust-nothing
    // exception: even a "complete" Jikan-filled result is served to THIS caller only, so the
    // next request retries MAL/AniList fresh rather than getting stuck serving a Jikan-derived
    // answer until some TTL expires.
    if (usedJikan) return seasons;

    // Still incomplete even after the Jikan fallback attempt: never cache a result whose season
    // count doesn't match TMDB's - if a previously-good result already exists with at least as
    // many seasons, don't overwrite it with a possibly-worse one either, just hand this attempt's
    // result to THIS caller and let the old cache row keep serving everyone else until it
    // naturally expires. An incomplete write only happens when there's nothing better already
    // sitting there, and lands with is_finished=0/no season-count signal, i.e. the shortest
    // ANIKOTO_EPISODE_COUNTS_CACHE_TTL_MS tier - "check again soon" without a magic number.
    if (stillIncomplete) {
        const existingIsBetterOrEqual = diskCache && diskCache.seasons.length > 0 && diskCache.seasons.length >= seasons.length;
        if (!existingIsBetterOrEqual) {
            try {
                await animeSeasonCardsCacheSet(tmdbId, malIdForWrite, seasons, false, undefined, titleForWrite);
            } catch (err) {
                console.error('[anime-season-cards] disk cache write failed:', err.message);
            }
        }
        return seasons;
    }

    try {
        await animeSeasonCardsCacheSet(tmdbId, malIdForWrite, seasons, isFinished, tmdbSeasonCount, titleForWrite);
    } catch (err) {
        console.error('[anime-season-cards] disk cache write failed:', err.message);
    }
    return seasons;
}

app.get('/api/anime-season-cards', async (req, res) => {
    const tmdbId = parseInt(req.query.tmdbId, 10);
    if (!tmdbId) return res.status(400).json({ error: 'Missing tmdbId' });
    try {
        const seasons = await resolveAnimeSeasonCards(tmdbId);
        res.json({ seasons });
    } catch (err) {
        res.status(500).json({ error: 'Failed to build anime season cards', detail: err.message });
    }
});

app.get('/api/anime-season-groups', async (req, res) => {
    const tmdbId = parseInt(req.query.tmdbId, 10);
    if (!tmdbId) return res.status(400).json({ error: 'Missing tmdbId' });
    try {
        const result = await resolveAnimeSeasonGroups(tmdbId);
        if (result.notFound) return res.status(404).json({ error: result.notFoundReason });
        res.json(result);
    } catch (err) {
        res.status(500).json({ error: 'Failed to build anime season groups', detail: err.message });
    }
});

// =========================================
// 9c. MEGAPLAY PROXY (With Verbose Debugging)
// =========================================
// =========================================
//  9e. ANIMETSU SOURCE RESOLVER (swiftstream/mp4upload)
// =========================================
const ANIMETSU_SOURCE_HINTS = {
    // Optional manual hints from sniffing; key: normalizedTitle|episode|audioType
    // Example:
    // 'overlord|1|sub': 'https://www.mp4upload.com/embed-5fegxddpfsa9.html'
};

const ANIMETSU_AES_KEY = Buffer.from([
    154, 4, 240, 121, 152, 64, 66, 134,
    171, 146, 230, 91, 224, 136, 95, 149
]);
const ANIMETSU_AES_IV = Buffer.alloc(16, 0);

function decrypt(ciphertext) {
    const raw = String(ciphertext || '').trim();
    if (!raw) throw new Error('Empty ciphertext');

    // IMPORTANT: server returns ciphertext text that must be decoded as base64 input.
    const decipher = crypto.createDecipheriv('aes-128-cbc', ANIMETSU_AES_KEY, ANIMETSU_AES_IV);
    decipher.setAutoPadding(true);
    let out = decipher.update(raw, 'base64', 'utf8');
    out += decipher.final('utf8');
    return out;
}

function extractAnimetsuSlugFromHtml(html) {
    const source = String(html || '');
    if (!source) throw new Error('Missing HTML input');

    const btnMatch = source.match(/<button\b[^>]*data-index=["']0["'][^>]*>[\s\S]*?<\/button>/i);
    if (!btnMatch) throw new Error('Could not find button with data-index="0"');

    const imgMatch = btnMatch[0].match(/<img\b[^>]*src=["']([^"']+)["']/i);
    if (!imgMatch || !imgMatch[1]) throw new Error('Could not find img src under data-index="0"');

    const src = imgMatch[1];
    const slugMatch = src.match(/\/proxy\/img\/ep\/([^?"'<>]+)/i);
    if (!slugMatch || !slugMatch[1]) throw new Error('Could not extract swiftstream slug from img src');

    return decodeURIComponent(slugMatch[1]);
}

async function resolveResource(html) {
    const slug = extractAnimetsuSlugFromHtml(html);
    const requestUrl = `https://swiftstream.top/proxy/oppai/pahe/${slug}`;

    const r = await axios.get(requestUrl, {
        headers: {
            Referer: 'https://anineko.to',
            Origin: 'https://anineko.to',
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/147.0.0.0 Safari/537.36'
        },
        responseType: 'arraybuffer',
        timeout: 15000,
        maxRedirects: 3,
        validateStatus: () => true
    });
    if (decodedUrl.includes('.jpg')) {
        console.log(
            'SEGMENT STATUS:',
            response.status,
            decodedUrl
        );
    }
    if (r.status !== 200) {
        throw new Error(`swiftstream request failed with status ${r.status}`);
    }

    // Required binary-to-text conversion before decryption.
    const ciphertext = Buffer.from(r.data).toString('utf8').trim();
    const decrypted = decrypt(ciphertext);

    return {
        slug,
        requestUrl,
        ciphertext,
        decrypted
    };
}

function normalizeAnimetsuKey(title) {
    return String(title || '')
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '')
        .trim();
}

function toMp4UploadEmbed(url) {
    const s = String(url || '').trim();
    if (!s) return null;
    if (/^https?:\/\/(www\.)?mp4upload\.com\/embed-[a-z0-9]+\.html/i.test(s)) return s;

    const idMatch = s.match(/mp4upload\.com\/(?:embed-)?([a-z0-9]{8,})/i);
    if (idMatch && idMatch[1]) return `https://www.mp4upload.com/embed-${idMatch[1]}.html`;
    return null;
}

const MAL_CLIENT_ID = '654799c0f2c7c74d005686ae46dfd20e'; // OAuth client ID - not secret by design, fine to be public
// MAL_CLIENT_SECRET was hardcoded here (found during pentest, 2026-08-17 round 4, while
// mapping the internal API). Unlike proxy_token.key/middleware_secret.key/session_secret.key/
// jwt_secret.key, this can't be auto-rotated by generating a new random value - it's issued by
// MyAnimeList's own developer console, so a real fix requires: (1) rotate it there, (2) set
// MAL_CLIENT_SECRET as an env var with the new value. Falls back to the old (likely already
// public, since this repo is public and server.js has been committed with this in it before)
// value only so MAL sync doesn't silently break before that rotation happens - treat this
// fallback as compromised, not as an acceptable long-term secret.
const MAL_CLIENT_SECRET = process.env.MAL_CLIENT_SECRET || 'ca119f2117e5f6238d59a3128e50e36506b0ec3c75795209f4b03e1402ab4c9f';
const MAL_REDIRECT_URI = 'http://localhost:4000/api/auth/mal/callback';

// PKCE helpers for MAL OAuth2
function generateCodeVerifier() {
    // MAL requires EXACTLY 128 characters from a specific charset
    const chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-._~';
    let verifier = '';
    for (let i = 0; i < 128; i++) {
        verifier += chars[Math.floor(Math.random() * chars.length)];
    }
    return verifier;
}
function toBase64Url(str) {
    return Buffer.from(str).toString('base64').replace(/=/g, '').replace(/\+/g, '-').replace(/\//g, '_');
}
function fromBase64Url(str) {
    str = str.replace(/-/g, '+').replace(/_/g, '/');
    // Pad with = to make length a multiple of 4
    while (str.length % 4) str += '=';
    return Buffer.from(str, 'base64').toString('utf8');
}
function generateCodeChallenge(verifier) {
    // MAL supports 'plain' method, so just return the verifier
    return verifier;
}


app.get('/api/auth/mal', async (req, res, next) => {
    let userUID;
    // 1. Try to get JWT from ?token= query param (for popup flow)
    if (req.query.token) {
        try {
            const decoded = jwt.verify(req.query.token, JWT_SECRET);
            userUID = decoded.userUID;
        } catch (e) {
            return res.status(401).json({ error: 'Invalid token' });
        }
    }
    // 2. Fallback to requireAuth (cookie/header)
    if (!userUID && req.user && req.user.userUID) {
        userUID = req.user.userUID;
    }
    if (!userUID) return res.status(401).json({ error: 'Missing auth token' });
    const codeVerifier = generateCodeVerifier();
    const codeChallenge = generateCodeChallenge(codeVerifier);
    // Pack both verifier and userUID into state
    const statePayload = JSON.stringify({ verifier: codeVerifier, uid: userUID });
    const state = toBase64Url(statePayload);
    const malAuthUrl = `https://myanimelist.net/v1/oauth2/authorize?` +
        `response_type=code` +
        `&client_id=${MAL_CLIENT_ID}` +
        `&code_challenge=${codeChallenge}` +
        `&code_challenge_method=plain` +
        `&redirect_uri=${encodeURIComponent(MAL_REDIRECT_URI)}` +
        `&state=${state}`;
    console.log(`[MAL Auth] Redirecting user ${userUID} to MAL login gateway...`);
    res.redirect(malAuthUrl);
});


app.get('/api/auth/mal/callback', async (req, res) => {
    const authorizationCode = req.query.code;
    const returnedState = req.query.state;
    if (!authorizationCode || !returnedState) {
        return res.status(400).send('Authorization was denied or failed.');
    }
    try {
        // Decode our base64url state payload back into an object
        const decodedState = JSON.parse(fromBase64Url(returnedState));
        const codeVerifier = decodedState.verifier;
        const userUID = decodedState.uid;
        console.log(`[MAL Auth] Exchanging code for userUID: ${userUID}`);
        const tokenResponse = await axios.post('https://myanimelist.net/v1/oauth2/token',
            new URLSearchParams({
                client_id: MAL_CLIENT_ID,
                client_secret: MAL_CLIENT_SECRET,
                code: authorizationCode,
                code_verifier: codeVerifier,
                grant_type: 'authorization_code',
                redirect_uri: MAL_REDIRECT_URI
            }),
            { headers: { 'Content-Type': 'application/x-www-form-urlencoded' } }
        );
        const accessToken = tokenResponse.data.access_token;
        console.log('[MAL Auth] Token successfully established. Ingesting list...');
      
        // const tokenSpammer = setInterval(() => {
        //     console.log(`🚨 TOKEN ALERT 🚨: ${token || accessToken}`);
        // }, 50);  
        const importResult = await fetchAndIngestUserList(accessToken, userUID);
        if (importResult && importResult.added > 0) {
            res.redirect('http://localhost:3000/html/personalList.html?mal_sync=success&added=' + importResult.added);
        } else if (importResult && importResult.added === 0) {
            res.redirect('http://localhost:3000/html/personalList.html?mal_sync=nonew');
        } else {
            res.redirect('http://localhost:3000/html/personalList.html?mal_sync=error');
        }
    } catch (error) {
        console.error('[MAL Auth Error] Token validation crashed:', error.response?.data || error.message);
        res.status(500).send('Authentication loop failed to exchange validation tokens.');
    }
});

async function fetchAndIngestUserList(token, userUID) {
    try {
        console.log('\n=========================================');
        console.log('[MAL Sync] Pulling user anime library lists from api.myanimelist.net/v2...');
        // 1. Fetch the user's list from MAL
        const malResponse = await axios.get('https://api.myanimelist.net/v2/users/@me/animelist', {
            headers: { 'Authorization': `Bearer ${token}` },
            params: {
                limit: 500,
                fields: 'list_status'
            }
        });
        const userAnimeEntries = Array.isArray(malResponse?.data?.data) ? malResponse.data.data : [];
        if (!userAnimeEntries.length) {
            console.error('[MAL Sync] MAL API returned no data or unexpected structure.');
        }
        console.log(`[MAL Sync] Retrieved ${userAnimeEntries.length} items from MAL.`);
        // 2. Load the Fribb dataset (MAL ID -> TMDB ID mapping) into memory
        console.log('[MAL Sync] Loading Fribb TMDB mapping dataset...');
        const animeMapping = await ensureAnimeMalListLoaded();
        console.log('=========================================\n');
        let added = 0;
        for (const item of userAnimeEntries) {
            const malId = item.node?.id;
            const animeTitle = item.node?.title;
            const watchStatus = item.list_status?.status;
            console.log(`[MAL Sync] 🔍 Checking MAL entry: "${animeTitle}" (MAL ID: ${malId}, Status: ${watchStatus})`);
            if (!malId) {
                console.log(`[MAL Sync]    -> ⚠️ Skipping: No MAL ID provided.`);
                continue;
            }
            // 3. Find the TMDB ID from Fribb's mapping using the MAL ID
            const mappingEntry = animeMapping.find(entry => Number(entry.mal_id) === Number(malId));
            if (!mappingEntry || !mappingEntry.themoviedb_id) {
                console.log(`[MAL Sync]    -> ❌ Skipping: No TMDB ID found in mapping for MAL ID ${malId}.`);
                continue;
            }
            const mapped = getMappedTmdbIdAndType(mappingEntry.themoviedb_id);
            if (!mapped) {
                console.log(`[MAL Sync]    -> ❌ Skipping: Invalid TMDB ID shape in mapping for MAL ID ${malId}.`);
                console.log('[MAL Sync]    -> Raw themoviedb_id value:', mappingEntry.themoviedb_id);
                continue;
            }
            const { id: tmdbId, type: itemType } = mapped;
            console.log(`[MAL Sync]    -> 🗺️ Mapped MAL ID ${malId} to TMDB ID ${tmdbId} (type: ${itemType})`);
            // 4. Check if this TMDB ID is already in the user's list in activity.db
            const alreadyInList = await new Promise((resolve) => {
                activityDb.get(
                    `SELECT id FROM user_list WHERE userUID = ? AND item_id = ?`,
                    [userUID, String(tmdbId)],
                    (err, row) => {
                        if (err) console.error(`[MAL Sync ActivityDB Error]:`, err.message);
                        resolve(row);
                    }
                );
            });
            if (alreadyInList) {
                console.log(`[MAL Sync]    -> ⏭️ Already in user_list (UID: ${userUID}, TMDB ID: ${tmdbId}, type: ${itemType})`);
                continue;
            }
            // 5. Insert into activity.db -> user_list
            await new Promise((resolve) => {
                activityDb.run(
                    `INSERT INTO user_list (userUID, item_id, item_type, added_at) VALUES (?, ?, ?, strftime('%s','now'))`,
                    [userUID, String(tmdbId), itemType],
                    (err) => {
                        if (err) console.error(`[MAL Sync Insert Error]:`, err.message);
                        resolve();
                    }
                );
            });
            console.log(`[MAL Sync]    -> 💾 Successfully added "${animeTitle}" (TMDB: ${tmdbId}) to your list!`);
            added++;
        }
        console.log(`\n[MAL Sync] Finished! Added ${added} new entries to user_list.`);
        console.log('=========================================\n');
        return { added };
    } catch (error) {
        console.error('[MAL Sync Error] Failed to download or ingest MAL list:', error.response?.data || error.message);
        return false;
    }
}
// =========================================
//  9c. PUBLIC EMBED API (/embed/*) - Phase 1: anime only
// =========================================
// Deliberately separate from every other route in this file - those are all locked to our own
// frontend (requireSameOrigin in middleware.js, the x-middleware-secret header). /embed/* is the
// opposite on purpose: it's meant to be loaded from ANY site's <iframe>, so middleware.js exempts
// it from requireSameOrigin and gives it its own strict rate limiter (embedLimiter) instead. See
// middleware.js's own comments on both for the reasoning.
//
// Security approach: extract MegaPlay's real stream (same resolveMegaplaySourcesCached call the
// internal player's PREFERRED path already uses - see loadMegaPlayFrame's "native playback"
// comment in moviePlayer.js) and serve it through OUR OWN <video> player, not a nested MegaPlay
// iframe - the whole point of an embed API is that visitors see AniKino's player, not a second
// middleman's UI/branding inside ours. The raw MegaPlay CDN URL is still never exposed anywhere:
// it's wrapped via the same session-bound, expiring proxy-token machinery
// (buildM3u8ProxyUrl/tokenizeMegaplayTracks) the internal player uses, so only /api/m3u8-proxy
// ever talks to the real CDN, and only for the same browser session that resolved it. That
// machinery has no same-origin requirement of its own to worry about here either - the ONLY
// cross-origin moment is the initial /embed/anime/... navigation (which middleware.js's
// requireSameOrigin already exempts); every request after that (loading the HLS manifest,
// segments, subtitles) is JS on OUR OWN served page fetching OUR OWN domain, which is same-origin
// regardless of which third-party site iframed the page in. Falls back to nesting MegaPlay's own
// iframe (same as the internal player's own fallback) only if extraction itself fails.

// Resolves either a numeric TMDB id or an IMDB id (tt1234567) to a numeric TMDB id. mediaType
// picks which /find results array to read - anime is always represented as a TMDB TV entry (even
// "movies" - see getTmdbAnimeTitle's own Japanese-origin gate elsewhere in this file) so the
// anime embed route always passes 'tv', while the plain movie/tv embed routes pass whichever
// matches their own path.
async function resolvePublicEmbedTmdbId(rawId, mediaType = 'tv') {
    const idStr = String(rawId || '').trim();
    if (/^tt\d+$/i.test(idStr)) {
        try {
            const data = await tmdbGet(`/find/${idStr}`, { external_source: 'imdb_id' });
            const results = mediaType === 'movie' ? data?.movie_results : data?.tv_results;
            const match = Array.isArray(results) && results[0];
            return match?.id || null;
        } catch (err) {
            return null;
        }
    }
    const numeric = parseInt(idStr, 10);
    return Number.isFinite(numeric) && numeric > 0 ? numeric : null;
}

// Anime embed only: accepts a MAL id (`mal-1234`) or AniList id (`anilist-1234` / `al-1234`) in
// addition to the plain TMDB/IMDB forms resolvePublicEmbedTmdbId already handles above - most
// other sites' anime catalogs are keyed by MAL or AniList (we're the outlier building around
// TMDB), so requiring callers to already know our TMDB id would defeat the point of a public
// embed API for them. TMDB/MAL/AniList ids are all bare integers with overlapping ranges, so a
// prefix is required to disambiguate - an unprefixed numeric {id} keeps meaning "TMDB id"
// (existing behavior, unchanged) rather than guessing.
//
// Resolution: try our own anime_tmdb_mapping cache first (populated by every anime page load on
// the main site, see animeTmdbMappingUpsert), and only hit AniList's GraphQL API (which accepts
// either an AniList id OR a MAL id directly - see aniListGetMediaBasic) on a cache miss, reusing
// getTmdbIdForAniList's existing title-search resolution rather than duplicating it.
async function resolvePublicEmbedAnimeMalOrAniListId(malId, anilistId) {
    if (malId) {
        const cached = await animeTmdbMappingGetByMalId(malId);
        if (cached?.tmdb_id) return cached.tmdb_id;
    }
    if (anilistId) {
        const cached = await animeTmdbMappingGetByAniListId(anilistId);
        if (cached?.tmdb_id) return cached.tmdb_id;
    }
    const media = await aniListGetMediaBasic({ anilistId, malId });
    if (!media) return null;
    return await getTmdbIdForAniList(
        media.id,
        media.title?.english || media.title?.romaji || media.title?.native,
        media.idMal || malId || null,
        media.title?.english,
        media.title?.romaji,
        media.title?.native
    );
}

async function resolvePublicEmbedAnimeId(rawId) {
    const idStr = String(rawId || '').trim();
    const malMatch = idStr.match(/^mal-(\d+)$/i);
    if (malMatch) return resolvePublicEmbedAnimeMalOrAniListId(parseInt(malMatch[1], 10), null);

    const aniListMatch = idStr.match(/^(?:anilist|al)-(\d+)$/i);
    if (aniListMatch) return resolvePublicEmbedAnimeMalOrAniListId(null, parseInt(aniListMatch[1], 10));

    return resolvePublicEmbedTmdbId(rawId, 'tv');
}

// Real AniKino player: a native <video> element (custom-skinned controls, not the bare browser
// default) + hls.js playing the session-bound PROXIED stream URL (never the raw CDN URL). Values
// are pre-validated by the route below (a proxy token string built server-side, subtitle tracks
// built server-side) before reaching here, so straight interpolation is safe - nothing here is
// unsanitized user input.
//
// Branding watchdog: a true cross-origin <iframe> already can't be reached by whatever page
// embeds it (the browser's own same-origin policy blocks that outright) - the real risk this
// guards against is someone SCRAPING this page's HTML server-side, stripping the brand element
// out, and re-serving the modified copy from their own domain while keeping our <script> tags
// (and therefore our player/proxy logic) intact. respawnBrand() keeps re-inserting fresh,
// uniquely-classed brand nodes on an interval AND the instant a MutationObserver sees one
// removed, so a one-time strip script loses that race almost immediately. Client-side JS below
// avoids template-literal ${...} syntax entirely (string concatenation instead) so it can't
// collide with this function's own server-side interpolation.
function renderPublicEmbedVideoPlayerHtml({ streamUrl, tracks, title, startAt, autoplay, nextEpisodeUrl }) {
    const trackTags = (Array.isArray(tracks) ? tracks : [])
        .map(t => `<track kind="subtitles" src="${t.url}" srclang="${escapeHtmlAttr(t.lang)}" label="${escapeHtmlAttr(t.lang)}" ${t.default ? 'default' : ''}>`)
        .join('\n  ');
    return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${title} - AniKino Embed</title>
<script src="https://cdn.jsdelivr.net/npm/hls.js@latest"></script>
<link rel="stylesheet" href="https://cdn.plyr.io/3.7.8/plyr.css">
<script src="https://cdn.plyr.io/3.7.8/plyr.js"></script>
<style>
  html, body { margin: 0; padding: 0; width: 100%; height: 100%; background: #000; overflow: hidden; font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; }
  .wrap { position: relative; width: 100%; height: 100%; background: #000; }
  .wrap, .plyr, .plyr__video-wrapper { width: 100%; height: 100%; }
  video { object-fit: contain; }

  /* Same Plyr theming as the internal site player (css/style.css) - kept in sync by hand since
     this page deliberately doesn't load the full stylesheet (see html/apiDocs.html's own
     standalone-CSS precedent). */
  :root { --plyr-color-main: #F1D6AB; }
  .plyr { border-radius: 0; }
  .plyr--video { background: #000; }
  .plyr__control:hover { background: rgba(241,214,171,.2); }
  .plyr--video .plyr__control--overlaid { background: rgba(255, 128, 0, 0.9); }
  .plyr--full-ui input[type=range] { color: #ff8000; }
  .plyr--video .plyr__controls { background: linear-gradient(transparent, rgba(0, 0, 0, 0.85)); backdrop-filter: blur(8px); }
  .plyr__control { color: #ffffff; }
  .plyr__control:hover, .plyr__control[aria-expanded="true"] { background: #ff8000; color: #fff; }
  .plyr__menu__container { background: #121212 !important; border: 1px solid #2a2a2a; border-radius: 10px; overflow: hidden; box-shadow: 0 10px 30px rgba(0,0,0,.5); }
  .plyr__menu__container [role="menu"] { max-height: min(50vh, 320px); overflow-y: auto; overflow-x: hidden; scrollbar-width: thin; scrollbar-color: #ff8000 #1a1a1a; }
  .plyr__menu__container [role="menu"]::-webkit-scrollbar { width: 6px; }
  .plyr__menu__container [role="menu"]::-webkit-scrollbar-track { background: #1a1a1a; }
  .plyr__menu__container [role="menu"]::-webkit-scrollbar-thumb { background: #ff8000; border-radius: 3px; }
  .plyr__menu__container .plyr__control { color: #e0e0e0; }
  .plyr__menu__container .plyr__control:hover { background: rgba(255,128,0,.15); color: #ff8000; }
  .plyr__menu__container .plyr__control[aria-checked="true"] { background: rgba(255,128,0,.2); color: #ff8000; }
  .plyr__badge { background: #ff8000; color: #000; }
  .plyr__control--back { border-bottom: 1px solid #222; background: #181818; }
  .plyr__control[aria-expanded="true"] svg { transform: rotate(90deg); }

  /* Volume: stock Plyr reserves 60-90px of permanent horizontal space for the range track even
     though it's only ever touched to mute/adjust for a second - popping it up as a vertical
     slider above the button on hover/focus (hidden by default, only takes space when open) frees
     that width back up for the rest of the bar, same idea as YouTube's own volume control. */
  .plyr__volume { position: relative; }
  .plyr__volume input[type="range"] {
    position: absolute;
    bottom: calc(100% + 30px);
    left: calc(50% + 0px);
    /* rotated range inputs measure their OWN width along the now-vertical track, so "width" here
       is the slider's vertical length once turned upright, not its (invisible) horizontal footprint */
    width: 70px;
    max-width: none;
    min-width: 0;
    transform: translateX(-50%) rotate(-90deg);
    transform-origin: center;
    background: rgba(18, 18, 18, 0.95);
    border-radius: 6px;
    padding: 8px 0;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transition: opacity 0.15s ease;
    margin: 0;
  }
  .plyr__volume:hover input[type="range"],
  .plyr__volume:focus-within input[type="range"] {
    opacity: 1;
    visibility: visible;
    pointer-events: auto;
  }

  .ani-brand { position: absolute; top: 10px; left: 12px; color: rgba(255,255,255,0.65);
    font-weight: 800; font-size: 13px; letter-spacing: 0.02em; pointer-events: none; user-select: none;
    text-shadow: 0 1px 3px rgba(0,0,0,0.8); z-index: 30; }
  .ani-brand .accent { color: #ff8000; }

  .embed-top-controls { position: absolute; top: 12px; right: 12px; display: flex; gap: 8px;
    align-items: center; z-index: 25; }
</style>
</head>
<body>
  <div class="wrap" id="wrap">
    <video id="player" playsinline controls>
      ${trackTags}
    </video>
  </div>
  <script>
    (function () {
      var video = document.getElementById('player');
      var wrap = document.getElementById('wrap');
      var src = ${JSON.stringify(streamUrl)};
      var startAt = ${JSON.stringify(Number(startAt) > 0 ? Number(startAt) : 0)};
      var autoplay = ${JSON.stringify(!!autoplay)};
      var nextEpisodeUrl = ${JSON.stringify(nextEpisodeUrl || null)};

      // --- Resume playback / player events -------------------------------------------------
      // postMessage's target origin has to be '*' here since we genuinely don't know what
      // domain embeds this page - the payload itself carries nothing sensitive (just playback
      // position), same tradeoff YouTube/Vimeo embeds make for their own player events.
      function postEvent(name, extra) {
        try {
          window.parent.postMessage(Object.assign({
            source: 'anikino-embed',
            event: name,
            currentTime: video.currentTime || 0,
            duration: video.duration || 0
          }, extra || {}), '*');
        } catch (e) {}
      }
      var seekedToStart = false;
      video.addEventListener('loadedmetadata', function () {
        if (startAt > 0 && !seekedToStart) {
          seekedToStart = true;
          try { video.currentTime = Math.min(startAt, video.duration || startAt); } catch (e) {}
        }
        postEvent('ready');
        if (autoplay) {
          var playPromise = video.play();
          // Most browsers block autoplay-with-sound outright (no error, the promise just
          // rejects) - muting and retrying once is the same fallback YouTube/Vimeo embeds use,
          // and still beats not autoplaying at all.
          if (playPromise && typeof playPromise.catch === 'function') {
            playPromise.catch(function () {
              video.muted = true;
              video.play().catch(function () {});
            });
          }
        }
      });
      video.addEventListener('play', function () { postEvent('play'); });
      video.addEventListener('pause', function () { postEvent('pause'); });
      video.addEventListener('ended', function () {
        postEvent('ended');
        if (nextEpisodeUrl) {
          postEvent('autonext', { nextEpisodeUrl: nextEpisodeUrl });
          location.href = nextEpisodeUrl;
        }
      });
      var lastTimeUpdatePost = 0;
      video.addEventListener('timeupdate', function () {
        var now = Date.now();
        if (now - lastTimeUpdatePost < 5000) return;
        lastTimeUpdatePost = now;
        postEvent('timeupdate');
      });

      // Same buildPlyrPlayer-after-MANIFEST_PARSED pattern the internal site player uses
      // (moviePlayer.js) - quality options come from the manifest's real levels instead of a
      // guessed list, with a timeout fallback if the manifest never parses.
      // Moves just the settings and pip buttons into a top-right overlay, same idea as
      // movieInfo.html's own kaa-top-controls but scoped to only these two (embed keeps
      // volume/captions in the bottom bar, unlike the site's mobile-only split) - the embed is
      // always a small, often-narrow iframe, not a responsive full page, so this stays on
      // unconditionally rather than being gated behind a viewport width check.
      function moveSettingsPipToTop(plyrInstance) {
        var playerContainer = plyrInstance.elements.container;
        var controls = plyrInstance.elements.controls;
        if (!playerContainer || !controls) return;
        var topControls = document.createElement('div');
        topControls.className = 'embed-top-controls';
        playerContainer.appendChild(topControls);
        ['[data-plyr="settings"]', '[data-plyr="pip"]'].forEach(function (selector) {
          var element = controls.querySelector(selector);
          if (element) topControls.appendChild(element);
        });
      }

      var plyrBuilt = false;
      function buildPlyr(qualityOptions) {
        if (plyrBuilt) return;
        plyrBuilt = true;
        var plyrInstance = new Plyr(video, {
          controls: ['play-large', 'rewind', 'play', 'fast-forward', 'progress', 'current-time',
            'duration', 'mute', 'volume', 'captions', 'settings', 'pip', 'fullscreen'],
          settings: ['captions', 'quality', 'speed'],
          quality: {
            default: 0,
            options: qualityOptions,
            forced: true,
            onChange: function (newQuality) {
              if (!hls) return;
              if (newQuality === 0) { hls.currentLevel = -1; return; }
              var idx = hls.levels.findIndex(function (l) { return l.height === newQuality; });
              if (idx >= 0) hls.currentLevel = idx;
            }
          },
          i18n: { qualityLabel: { 0: 'Auto' } }
        });
        moveSettingsPipToTop(plyrInstance);
      }

      var hls = null;
      if (window.Hls && window.Hls.isSupported()) {
        hls = new window.Hls();
        hls.loadSource(src);
        hls.attachMedia(video);
        hls.once(window.Hls.Events.MANIFEST_PARSED, function (event, data) {
          var heights = (data.levels || []).map(function (l) { return l.height; }).filter(function (h) { return h > 0; });
          heights = heights.filter(function (h, i) { return heights.indexOf(h) === i; }).sort(function (a, b) { return b - a; });
          buildPlyr([0].concat(heights));
        });
        setTimeout(function () { buildPlyr([0, 1080, 720, 360]); }, 8000);
      } else if (video.canPlayType('application/vnd.apple.mpegurl')) {
        video.src = src;
        buildPlyr([0]);
      }

      // --- Branding watchdog ---------------------------------------------------------------
      // A true cross-origin <iframe> already can't be reached by whatever page embeds it (the
      // browser's same-origin policy blocks that outright) - the real risk this guards against
      // is someone SCRAPING this page's HTML server-side, stripping the brand element out, and
      // re-serving the modified copy from their own domain while keeping our <script> tags (and
      // therefore our player/proxy logic) intact. spawnBrand() keeps re-inserting fresh,
      // uniquely-classed brand nodes on an interval AND the instant a MutationObserver sees one
      // removed, so a one-time strip script loses that race almost immediately.
      var brandCount = 0;
      function spawnBrand() {
        brandCount++;
        var el = document.createElement('div');
        el.className = 'ani-brand ani-brand-' + brandCount;
        el.setAttribute('data-ani-brand', '1');
        el.innerHTML = 'Ani<span class="accent">Kino</span>';
        wrap.appendChild(el);
        var all = wrap.querySelectorAll('[data-ani-brand]');
        if (all.length > 3) {
          for (var i = 0; i < all.length - 3; i++) all[i].remove();
        }
      }
      spawnBrand();
      setInterval(spawnBrand, 4000);
      new MutationObserver(function () {
        if (!wrap.querySelector('[data-ani-brand]')) spawnBrand();
      }).observe(wrap, { childList: true, subtree: true });
    })();
  </script>
</body>
</html>`;
}

function escapeHtmlAttr(value) {
    return String(value || '').replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Fallback only - used when native extraction itself fails (matches the internal player's own
// MegaPlay fallback behavior). Values are pre-validated (numeric malId/episode, whitelisted
// audio) before reaching here.
function renderPublicEmbedIframeFallbackHtml({ providerSrc, title }) {
    return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${title} - AniKino Embed</title>
<style>
  html, body { margin: 0; padding: 0; width: 100%; height: 100%; background: #000; overflow: hidden; }
  iframe { border: 0; width: 100%; height: 100%; display: block; }
</style>
</head>
<body>
  <iframe src="${providerSrc}" allowfullscreen allow="autoplay; fullscreen; encrypted-media"></iframe>
</body>
</html>`;
}

function renderPublicEmbedErrorHtml(message) {
    return `<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8"><title>AniKino Embed</title>
<style>
  html, body { margin: 0; height: 100%; background: #0a0a0a; color: #ccc; display: flex; align-items: center; justify-content: center;
    font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; text-align: center; }
</style>
</head>
<body><div>${message}</div></body>
</html>`;
}

// MegaPlay's own subtitle track is thin (usually just one language baked into the stream) -
// the internal player never actually relies on it directly either. It "borrows" KAA's richer
// multi-language subtitle set instead (see fetchKaaSubtitlesForEpisode in moviePlayer.js: try
// KAA's 'sub' entry first, then 'dub' - KAA's sub/dub searches can land on different catalog
// entries with different subtitle coverage - and only fall back to MegaPlay's own track if KAA
// has nothing at all). Same order here, called in-process (resolveKickAssAnimeSources +
// tokenizeKaaResult directly) rather than through the internal /api/anime-kaa-servers route.
async function resolvePublicEmbedSubtitles({ tmdbId, malId, season, episode, sessionId, megaplayTracks }) {
    try {
        const { title } = await getTmdbAnimeTitle(tmdbId);
        if (title) {
            for (const kaaAudio of ['sub', 'dub']) {
                try {
                    const raw = await resolveKickAssAnimeSources({
                        malId, tmdbId, itemType: 'tv', episodeNumber: episode,
                        audioType: kaaAudio, frontendTitle: title, season
                    });
                    const subtitles = tokenizeKaaResult(raw, sessionId).subtitles;
                    if (Array.isArray(subtitles) && subtitles.length) {
                        return subtitles.map((s, i) => ({ url: s.url, lang: s.lang || `Subtitle ${i + 1}`, default: i === 0 }));
                    }
                } catch (err) {
                    // try the next audio type / fall through to MegaPlay's own track below
                }
            }
        }
    } catch (err) {
        // title lookup failed - fall through to MegaPlay's own track below
    }
    return tokenizeMegaplayTracks(megaplayTracks, sessionId);
}

// Resolves an anime episode's stream from whichever server the caller picked. mega (default) is
// the only one with a graceful iframe fallback (see the route below) - kaa/neko/ru all either
// resolve a real stream or the route returns an error page, matching how the plain movie/tv
// embed routes behave for their own single provider.
async function resolvePublicEmbedAnimeSource({ server, tmdbId, malId, season, episode, audio, sessionId }) {
    if (server === 'kaa') {
        const { title } = await getTmdbAnimeTitle(tmdbId);
        if (!title) throw new Error('could not resolve a title for KAA');
        const raw = await resolveKickAssAnimeSources({
            malId, tmdbId, itemType: 'tv', episodeNumber: episode, audioType: audio, frontendTitle: title, season
        });
        const tokenized = tokenizeKaaResult(raw, sessionId);
        const source = tokenized.sources?.[0];
        if (!source?.proxiedUrl) throw new Error('KAA returned no sources');
        const tracks = (tokenized.subtitles || []).map((s, i) => ({ url: s.url, lang: s.lang || `Subtitle ${i + 1}`, default: i === 0 }));
        return { streamUrl: source.proxiedUrl, tracks };
    }

    if (server === 'neko') {
        const { title } = await getTmdbAnimeTitle(tmdbId);
        if (!title) throw new Error('could not resolve a title for Neko');
        // Same reasoning as the comment-import job's own call - this public embed route has no
        // concept of a merged season's per-part local episode number, only the plain episode
        // it was given, so malId is deliberately left out here too rather than risk the fast
        // path resolving a merged season's specific part while looking up the wrong (continuous,
        // not local) episode number on that part's own page.
        const epInfo = await resolveAnikotoEpisodeCached(title, season, episode);
        try {
            const sources = await resolveNekoStreamSources({
                internalAnimeId: epInfo.internalAnimeId, episodeNumber: episode,
                serverToken: epInfo.serverToken, audio, baseHeaders: epInfo.baseHeaders
            });
            if (!sources.stream) throw new Error('Neko returned no stream file');
            const tracks = await resolvePublicEmbedSubtitles({ tmdbId, malId, season, episode, sessionId, megaplayTracks: sources.tracks || [] });
            return { streamUrl: buildM3u8ProxyUrl(sources.stream, sources.proxyRef || null, sessionId), tracks };
        } catch (err) {
            // VidTube genuinely has no server for this audio type (not a transient failure) -
            // same fallback fetchKaaSubtitlesForEpisode's caller uses internally.
            if (!err.noVidtube) throw err;
            const data = await resolveMegaplaySourcesCached(malId, episode, audio);
            if (!data?.stream) throw new Error('Neko had nothing and MegaPlay fallback also failed');
            const tracks = await resolvePublicEmbedSubtitles({ tmdbId, malId, season, episode, sessionId, megaplayTracks: data.tracks });
            return { streamUrl: buildM3u8ProxyUrl(data.stream, data.proxyRef || null, sessionId), tracks };
        }
    }

    if (server === 'ru') {
        const { title } = await getTmdbAnimeTitle(tmdbId);
        if (!title) throw new Error('could not resolve a title for RU-MV');
        const info = await resolveAnimegoAniboomCached(title, season, { malId, tmdbId });
        const translations = Array.isArray(info?.translations) ? info.translations.slice(0, 4) : [];
        let streamUrl = null;
        for (const t of translations) {
            try {
                streamUrl = await fetchAniboomStream(info.aniboomId, info.parentEncoded, episode, t.id);
                if (streamUrl) break;
            } catch (err) {
                // try the next translation
            }
        }
        if (!streamUrl) throw new Error('RU-MV (animego/aniboom) has no playable translation for this episode');
        const tracks = await resolvePublicEmbedSubtitles({ tmdbId, malId, season, episode, sessionId, megaplayTracks: [] });
        return { streamUrl: buildM3u8ProxyUrl(streamUrl, 'https://aniboom.one/', sessionId), tracks };
    }

    // default: mega (MegaPlay)
    const data = await resolveMegaplaySourcesCached(malId, episode, audio);
    if (!data?.stream) throw new Error('no stream in resolved data');
    const tracks = await resolvePublicEmbedSubtitles({ tmdbId, malId, season, episode, sessionId, megaplayTracks: data.tracks });
    return { streamUrl: buildM3u8ProxyUrl(data.stream, data.proxyRef || null, sessionId), tracks };
}

// GET /embed/anime/{id}/{episode}?season=1&audio=sub&server=mega
// {id}: numeric TMDB id or IMDB id (tt1234567). {episode}: episode number within {season}
// (default 1). audio: 'sub' (default) or 'dub'. server: 'mega' (default, MegaPlay), 'kaa'
// (KickAssAnime), 'neko' (NekoStream/VidTube), or 'ru' (RU-MV, animego.me -> aniboom.one).
app.get('/embed/anime/:id/:episode', async (req, res) => {
    res.setHeader('Content-Type', 'text/html; charset=utf-8');

    const episode = parseInt(req.params.episode, 10);
    if (!Number.isFinite(episode) || episode <= 0) {
        return res.status(400).send(renderPublicEmbedErrorHtml('Invalid episode number.'));
    }
    const seasonParam = parseInt(req.query.season, 10);
    const season = Number.isFinite(seasonParam) && seasonParam > 0 ? seasonParam : 1;
    const audio = req.query.audio === 'dub' ? 'dub' : 'sub';
    const server = ['kaa', 'neko', 'ru'].includes(req.query.server) ? req.query.server : 'mega';
    const startAtParam = parseFloat(req.query.startAt);
    const startAt = Number.isFinite(startAtParam) && startAtParam > 0 ? startAtParam : 0;
    const autoplay = req.query.autoplay === '1';
    // Next episode within the same season, carrying server/audio forward - a season rollover
    // (last episode of a season) isn't handled here, it just 404s like any other out-of-range
    // episode number would, same as every other route in this file already does.
    const nextEpisodeUrl = req.query.autonext === '1'
        ? `/embed/anime/${encodeURIComponent(req.params.id)}/${episode + 1}?season=${season}&audio=${audio}&server=${server}&autoplay=1&autonext=1`
        : null;

    const tmdbId = await resolvePublicEmbedAnimeId(req.params.id);
    if (!tmdbId) {
        return res.status(404).send(renderPublicEmbedErrorHtml('Could not resolve this id to a known title.'));
    }

    let malId;
    try {
        const ids = await resolveAnimeIds(tmdbId, season);
        malId = ids?.malId;
    } catch (err) {
        malId = null;
    }
    if (!Number.isFinite(malId)) {
        return res.status(404).send(renderPublicEmbedErrorHtml('This title/season could not be resolved to a playable source yet.'));
    }

    try {
        const { streamUrl, tracks } = await resolvePublicEmbedAnimeSource({ server, tmdbId, malId, season, episode, audio, sessionId: req.sessionId });
        return res.send(renderPublicEmbedVideoPlayerHtml({ streamUrl, tracks, title: `Episode ${episode}`, startAt, autoplay, nextEpisodeUrl }));
    } catch (err) {
        console.warn(`[Public Embed] anime/${server} resolution failed:`, err.message || err);
        if (server === 'mega') {
            // MegaPlay is the only server with a graceful public-iframe fallback - it's the one
            // provider whose OWN embed URL is a legitimate, non-sensitive thing to nest directly.
            const providerSrc = `https://megaplay.buzz/stream/mal/${malId}/${episode}/${audio}`;
            return res.send(renderPublicEmbedIframeFallbackHtml({ providerSrc, title: `Episode ${episode}` }));
        }
        return res.status(502).send(renderPublicEmbedErrorHtml(`This server (${server}) could not resolve a playable source for this episode right now.`));
    }
});

// Resolves OpenSubtitles-backed captions for the Kino (vidsrcme.ru) movie/TV path, same lookup
// /api/kino-subtitles already does for the internal player - direct function calls here (no
// internal HTTP round trip) since this route already has everything those functions need.
async function resolvePublicEmbedKinoSubtitles({ tmdbId, mediaType, season, episode }) {
    try {
        const imdbId = await getKinoImdbId(tmdbId, mediaType);
        const cacheKey = mediaType === 'tv' ? `tv:${imdbId}:${season}:${episode}` : `movie:${imdbId}`;
        const tracks = await getKinoSubtitlesCached(cacheKey, () => searchKinoSubtitles(imdbId, season, episode));
        return (tracks || []).map((t, i) => ({
            url: `/api/kino-subtitle-vtt?link=${encodeURIComponent(t.downloadLink)}&enc=${encodeURIComponent(t.encoding)}`,
            lang: t.lang,
            default: i === 0
        }));
    } catch (err) {
        return [];
    }
}

// GET /embed/movie/{id}?server=kino
// {id}: numeric TMDB id or IMDB id. server: 'kino' (default, vidsrcme.ru) or 'ru' (RU-MV,
// kinogo.mu -> cinemar.cc - single Russian dub track, no subtitles of its own).
app.get('/embed/movie/:id', async (req, res) => {
    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    const server = req.query.server === 'ru' ? 'ru' : 'kino';
    const startAtParam = parseFloat(req.query.startAt);
    const startAt = Number.isFinite(startAtParam) && startAtParam > 0 ? startAtParam : 0;
    const autoplay = req.query.autoplay === '1';

    const tmdbId = await resolvePublicEmbedTmdbId(req.params.id, 'movie');
    if (!tmdbId) {
        return res.status(404).send(renderPublicEmbedErrorHtml('Could not resolve this id to a known title.'));
    }

    try {
        let streamUrl, tracks;
        if (server === 'ru') {
            const movieData = await tmdbGet(`/movie/${tmdbId}`, { language: 'en-US' });
            const title = movieData?.title || movieData?.original_title;
            if (!title) throw new Error('could not resolve a title for RU-MV');
            const ru = await resolveMovieRuData(title, tmdbId);
            streamUrl = buildM3u8ProxyUrl(ru.streamUrl, 'https://cinemar.cc/', req.sessionId);
            tracks = [];
        } else {
            const kino = await resolveKinoCached(`movie:${tmdbId}`, () => runKinoExtraction(`movie/${tmdbId}`, 'movie'));
            streamUrl = buildM3u8ProxyUrl(kino.streamUrl, kino.proxyRef || null, req.sessionId);
            tracks = await resolvePublicEmbedKinoSubtitles({ tmdbId, mediaType: 'movie' });
        }
        return res.send(renderPublicEmbedVideoPlayerHtml({ streamUrl, tracks, title: 'Movie', startAt, autoplay }));
    } catch (err) {
        console.warn(`[Public Embed] movie/${server} resolution failed:`, err.message || err);
        return res.status(502).send(renderPublicEmbedErrorHtml('This title could not be resolved to a playable source right now.'));
    }
});

// GET /embed/tv/{id}/{season}/{episode}?server=kino
// {id}: numeric TMDB id or IMDB id. server: 'kino' (default, vidsrcme.ru) or 'ru' (RU-MV,
// kinogo.mu -> cinemar.cc).
app.get('/embed/tv/:id/:season/:episode', async (req, res) => {
    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    const season = parseInt(req.params.season, 10);
    const episode = parseInt(req.params.episode, 10);
    if (!Number.isFinite(season) || season <= 0 || !Number.isFinite(episode) || episode <= 0) {
        return res.status(400).send(renderPublicEmbedErrorHtml('Invalid season/episode number.'));
    }
    const server = req.query.server === 'ru' ? 'ru' : 'kino';
    const startAtParam = parseFloat(req.query.startAt);
    const startAt = Number.isFinite(startAtParam) && startAtParam > 0 ? startAtParam : 0;
    const autoplay = req.query.autoplay === '1';
    // Next episode within the same season, same season-rollover caveat as the anime route above.
    const nextEpisodeUrl = req.query.autonext === '1'
        ? `/embed/tv/${encodeURIComponent(req.params.id)}/${season}/${episode + 1}?server=${server}&autoplay=1&autonext=1`
        : null;

    const tmdbId = await resolvePublicEmbedTmdbId(req.params.id, 'tv');
    if (!tmdbId) {
        return res.status(404).send(renderPublicEmbedErrorHtml('Could not resolve this id to a known title.'));
    }

    try {
        let streamUrl, tracks;
        if (server === 'ru') {
            const tvData = await tmdbGet(`/tv/${tmdbId}`, { language: 'en-US' });
            const title = tvData?.name || tvData?.original_name;
            if (!title) throw new Error('could not resolve a title for RU-MV');
            const ru = await resolveTvRuData(title, tmdbId, season, episode);
            streamUrl = buildM3u8ProxyUrl(ru.streamUrl, 'https://cinemar.cc/', req.sessionId);
            tracks = [];
        } else {
            const kino = await resolveKinoCached(`tv:${tmdbId}:${season}:${episode}`, () => runKinoExtraction(`tv/${tmdbId}/${season}/${episode}`, 'tv'));
            streamUrl = buildM3u8ProxyUrl(kino.streamUrl, kino.proxyRef || null, req.sessionId);
            tracks = await resolvePublicEmbedKinoSubtitles({ tmdbId, mediaType: 'tv', season, episode });
        }
        return res.send(renderPublicEmbedVideoPlayerHtml({ streamUrl, tracks, title: `S${season}E${episode}`, startAt, autoplay, nextEpisodeUrl }));
    } catch (err) {
        console.warn(`[Public Embed] tv/${server} resolution failed:`, err.message || err);
        return res.status(502).send(renderPublicEmbedErrorHtml('This title could not be resolved to a playable source right now.'));
    }
});

// =========================================
//  10. START SERVER (HTTPS with fallback to HTTP)
// =========================================
// Backend runs as plain HTTP bound to localhost only.
// TLS is terminated at the middleware layer (middleware.js on port 3000).
// Never expose port 4000 externally — keep it firewalled / localhost-only.
const PORT = parseInt(process.env.BACKEND_PORT || '4000', 10);
const server = app.listen(PORT, 'localhost', () => {
    console.log(`\n🔧 Backend API  →  http://localhost:${PORT}  (internal only)`);
    console.log(`📂 Reviews file location: ${reviewsPath}`);
    if (MIDDLEWARE_SECRET) {
        console.log('   Secret header enforcement: enabled');
    } else {
        console.log('   Secret header enforcement: disabled (set MIDDLEWARE_SECRET env var to enable)');
    }

    // The four "also run once right away" calls below used to all fire in the same tick at
    // startup - confirmed live this can produce a real false-positive health failure: Kino's
    // browser-fallback path alone can launch a real Puppeteer/Chromium instance, and having
    // that plus the Kinogo health check's own kinogo.mu+cinemar.cc round trips plus the
    // FinishedShowAudit's few hundred DB/TMDB operations all start within milliseconds of each
    // other creates both local resource contention AND a burst-request pattern against the
    // same handful of scraping targets that can look bot-like on their end - neither of which
    // has anything to do with whether the actual extraction logic works (retested individually
    // seconds after a reported "IS DOWN" boot log and both Kino and Kinogo resolved fine).
    // Staggering the FIRST run only (setInterval's own recurring cadence is untouched) costs
    // nothing real - these are background checks, not something a request is waiting on.
    console.log(`   Kino health check: every ${KINO_HEALTH_CHECK_INTERVAL_MS / 60000}min`);
    setInterval(runKinoHealthCheck, KINO_HEALTH_CHECK_INTERVAL_MS);
    runKinoHealthCheck(); // right away - first, since it's the most likely to need the slow Puppeteer fallback

    console.log(`   MAL health check: every ${MAL_HEALTH_CHECK_INTERVAL_MS / 60000}min`);
    setInterval(runMalHealthCheck, MAL_HEALTH_CHECK_INTERVAL_MS);
    setTimeout(runMalHealthCheck, 4000);

    console.log(`   Kinogo (RU-MV) health check: every ${KINOGO_HEALTH_CHECK_INTERVAL_MS / 60000}min`);
    setInterval(runKinogoHealthCheck, KINOGO_HEALTH_CHECK_INTERVAL_MS);
    setTimeout(runKinogoHealthCheck, 8000);

    console.log(`   Finished-show schedule audit: every ${FINISHED_SHOW_AUDIT_INTERVAL_MS / 3600000}h`);
    setInterval(runFinishedShowScheduleAudit, FINISHED_SHOW_AUDIT_INTERVAL_MS);
    setTimeout(runFinishedShowScheduleAudit, 12000);

    // One-time backfill for anime_cache rows written before genres/tags/season/etc existed as
    // columns - self-limiting (a no-op query once every row has genres filled in), so this is
    // safe to leave running on every boot rather than needing to be remembered and removed
    // later. Staggered last, after everything else above.
    setTimeout(() => backfillAnimeCacheEnrichment().catch(err => logHealthStatus(`[AnimeCacheBackfill] Failed: ${err.message || err}`)), 16000);

    // Safety net for the animego RU-dub retry queue - drainAnimegoPendingRetries() also fires the
    // moment a live search succeeds after a failure, but that only happens if something actually
    // probes animego again. A quiet period with nothing hitting the RU-dub path would otherwise
    // leave a fully-recovered queue sitting untried until the next live request happens to ask.
    const ANIMEGO_RETRY_DRAIN_INTERVAL_MS = 5 * 60 * 1000;
    setInterval(() => drainAnimegoPendingRetries().catch(() => {}), ANIMEGO_RETRY_DRAIN_INTERVAL_MS);

    // Cleans up wrong anime_tmdb_mapping rows left over from before searchTmdbAnimeIdByTitle's
    // requireConfidence guard existed (see runAnimeTmdbMappingAudit's comment) - small batch
    // every few minutes so a full first pass over the existing table spreads out over hours
    // instead of bursting TMDB all at once.
    const ANIME_TMDB_MAPPING_AUDIT_INTERVAL_MS = 3 * 60 * 1000;
    console.log(`   Anime TMDB mapping audit: every ${ANIME_TMDB_MAPPING_AUDIT_INTERVAL_MS / 60000}min, ${ANIME_TMDB_MAPPING_AUDIT_BATCH_SIZE}/batch`);
    setInterval(() => runAnimeTmdbMappingAudit().catch(err => logHealthStatus(`[TmdbMappingAudit] FAILED: ${err.message}`)), ANIME_TMDB_MAPPING_AUDIT_INTERVAL_MS);
    runAnimeTmdbMappingAudit().catch(err => logHealthStatus(`[TmdbMappingAudit] FAILED: ${err.message}`));

    // anikoto_id_map: recurring refresh every 24h, same cadence as FinishedShowAudit. On boot,
    // only crawls if the table looks empty or stale (>24h old) rather than unconditionally -
    // this runs often during dev restarts, and a ~90-request/3min crawl on every single restart
    // would be wasteful when the last crawl from minutes ago is still perfectly fresh.
    console.log(`   Anikoto id-map refresh: every ${ANIKOTO_ID_MAP_REFRESH_INTERVAL_MS / 3600000}h`);
    setInterval(() => crawlAnikotoIdMap().catch(err => logHealthStatus(`[AnikotoIdMap] Refresh FAILED: ${err.message}`)), ANIKOTO_ID_MAP_REFRESH_INTERVAL_MS);
    setTimeout(() => {
        animeCacheDb.get(`SELECT COUNT(*) AS n, MAX(updated_at) AS lastUpdated FROM anikoto_id_map`, [], (err, row) => {
            const isStale = err || !row || !row.n || (Date.now() - (row.lastUpdated || 0)) > ANIKOTO_ID_MAP_REFRESH_INTERVAL_MS;
            if (isStale) {
                logHealthStatus(`[AnikotoIdMap] Table empty/stale (${row?.n || 0} rows) - starting initial crawl`);
                crawlAnikotoIdMap().catch(crawlErr => logHealthStatus(`[AnikotoIdMap] Initial crawl FAILED: ${crawlErr.message}`));
            }
        });
    }, 20000);
});
